              <div className="w-full max-w-md h-4 bg-red-100 rounded-full overflow-hidden border border-red-200 mb-4"><div className="h-full bg-red-500 transition-all duration-300" style={{ width: `${(drillCount / DRILL_REQUIRED) * 100}%` }}></div></div>
