      <StatsModal isOpen={isStatsOpen} onClose={() => setIsStatsOpen(false)} avgWpm={avgWpmVal} history={testHistory} onPractice={() => {}} totalTime={0} joinDate={joinDate} streak={streak} userName={userName} setUserName={setUserName} completedTestsCount={testHistory.length} userXP={userXP} />
      <MusicPlayer isOpen={isMusicOpen} onClose={() => setIsMusicOpen(false)} settings={settings} setSettings={setSettings} userXP={userXP} />
    </div>
  );
};

export default App;

import { MechanicalSoundPreset } from '../types';

class SoundEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private enabled: boolean = true;
  private mechanicalEnabled: boolean = false; // Changed default to false
  private mechanicalPreset: MechanicalSoundPreset = 'THOCK';
  private masterVolume: number = 1.0;

  // Ambient/Generated Music components
  private ambientInterval: number | null = null;
  private ambientGain: GainNode | null = null;
  private ambientType: string = '';
  private ambientVolume: number = 0.5;

  // FX for Ambient
  private delayNode: DelayNode | null = null;
  private feedbackNode: GainNode | null = null;
  private lowpassNode: BiquadFilterNode | null = null;
  private compressorNode: DynamicsCompressorNode | null = null;

  // Cached Buffers (Optimization)
  private noiseBuffers: { [key: string]: AudioBuffer } = {};

  // Brown Noise specific (now part of ambient system)
  private brownNoiseSource: AudioBufferSourceNode | null = null;

  // Sequence State
  private seqIndex: number = 0;

  constructor() {
    try {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      // Pre-generate noise buffers to avoid GC stutter during playback
      if (this.ctx) {
        this.generateNoiseBuffer('white', 1.0); // 1 second of white noise
      }
    } catch (e) {
      console.warn("Web Audio API not supported");
    }
  }

  private generateNoiseBuffer(type: 'white', duration: number) {
    if (!this.ctx) return;
    const bufferSize = this.ctx.sampleRate * duration;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);

    for (let i = 0; i < bufferSize; i++) {
        // White noise
        data[i] = Math.random() * 2 - 1;
    }
    this.noiseBuffers[type] = buffer;
  }

  public setEnabled(enabled: boolean) {
    this.enabled = enabled;
  }

  public setMechanicalEnabled(enabled: boolean) {
    this.mechanicalEnabled = enabled;
  }

  public setMechanicalPreset(preset: MechanicalSoundPreset) {
    this.mechanicalPreset = preset;
  }

  public setAmbientVolume(volume: number) {
    this.ambientVolume = volume;
    if (this.ambientGain && this.ctx) {
        this.ambientGain.gain.setTargetAtTime(volume, this.ctx.currentTime, 0.2);
    }
  }

  public setAmbientMusic(presetId: string) {
    if (this.ambientType === presetId) return; // Already playing this preset

    this.stopAmbientMusic();

    if (presetId) {
      this.ambientType = presetId;
      this.startAmbientMusic();
    }
  }

  public stopAmbientMusic() {
    if (this.ambientInterval) {
      window.clearInterval(this.ambientInterval);
      this.ambientInterval = null;
    }

    // Fade out main ambient gain
    if (this.ambientGain && this.ctx) {
      const t = this.ctx.currentTime;
      this.ambientGain.gain.setValueAtTime(this.ambientGain.gain.value, t);
      this.ambientGain.gain.linearRampToValueAtTime(0, t + 1); 

      const oldGain = this.ambientGain;
      const oldSource = this.brownNoiseSource;

      setTimeout(() => {
        try { oldGain.disconnect(); } catch (e) {}
        if (oldSource) {
            try { oldSource.stop(); oldSource.disconnect(); } catch (e) {}
        }
      }, 1100);
    }

    this.ambientGain = null;
    this.brownNoiseSource = null;
    this.ambientType = '';
    this.seqIndex = 0;
  }

  private startAmbientMusic() {
    this.ensureContext();
    if (!this.ctx || !this.masterGain) return;

    // Master Gain for Ambient
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = this.ambientVolume;

    // Compressor to glue sounds together (especially drums)
    this.compressorNode = this.ctx.createDynamicsCompressor();
    this.compressorNode.threshold.value = -24;
    this.compressorNode.knee.value = 30;
    this.compressorNode.ratio.value = 12;
    this.compressorNode.attack.value = 0.003;
    this.compressorNode.release.value = 0.25;

    this.ambientGain.connect(this.compressorNode);
    // Connect to master gain instead of destination
    this.compressorNode.connect(this.masterGain);

    // Common FX Chain
    this.delayNode = this.ctx.createDelay();
    this.delayNode.delayTime.value = 0.4; 

    this.feedbackNode = this.ctx.createGain();
    this.feedbackNode.gain.value = 0.3; 

    this.lowpassNode = this.ctx.createBiquadFilter();
    this.lowpassNode.type = 'lowpass';
    this.lowpassNode.frequency.value = 2500;

    this.delayNode.connect(this.feedbackNode);
    this.feedbackNode.connect(this.delayNode);
    this.delayNode.connect(this.lowpassNode);
    this.lowpassNode.connect(this.ambientGain);

    switch (this.ambientType) {
        case 'PIANO_BEETHOVEN':
            this.playBeethovenPiano();
            break;
        case 'PIANO_SATIE':
            this.playSatiePiano();
            break;
        case 'PIANO_JAZZ':
            this.playJazzPiano();
            break;
        case 'ZEN':
            this.playProceduralZen();
            break;
        case 'BROWN_NOISE':
            this.playBrownNoise();
            break;
        case 'GUITAR':
            this.playAcousticGuitar();
            break;
        case 'DRUMS_HARDCORE':
            this.playHardcoreDrums();
            break;
        case 'SYNTH_COSMIC':
            this.playCosmicSynth();
            break;
    }
  }

  // --- Brown Noise ---
  private playBrownNoise() {
    if (!this.ctx || !this.ambientGain) return;

    const bufferSize = 2 * this.ctx.sampleRate; 
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);

    let lastOut = 0;
    for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;
        data[i] = (lastOut + (0.02 * white)) / 1.02;
        lastOut = data[i];
        data[i] *= 3.5; 
    }

    this.brownNoiseSource = this.ctx.createBufferSource();
    this.brownNoiseSource.buffer = buffer;
    this.brownNoiseSource.loop = true;

    // Separate filter for Brown Noise to make it cozy
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 400; 

    this.brownNoiseSource.connect(filter);
    filter.connect(this.ambientGain);

    this.brownNoiseSource.start(0);
  }

  // --- Piano Generators ---

  private playBeethovenPiano() {
    const Gs3 = 207.65; const Cs4 = 277.18; const E4 = 329.63;
    const A3 = 220.00; const D4 = 293.66; const Fs3 = 185.00;

    const sequence = [
        // Moonlight Sonata Arpeggios (Simplified)
        [Gs3, 0.6], [Cs4, 0.6], [E4, 0.6], 
        [Gs3, 0.6], [Cs4, 0.6], [E4, 0.6], 
        [A3, 0.6], [Cs4, 0.6], [E4, 0.6],
        [Fs3, 0.6], [A3, 0.6], [D4, 0.6],
    ];

    this.runSequence(sequence, (freq) => this.triggerPianoNote(freq, 'triangle'));
  }

  private playSatiePiano() {
    // Gymnopédie No.1 style (Slow 3/4)
    // Root, Chord, Chord pattern
    const Gmaj7 = [196.00, 246.94, 293.66, 369.99]; // G3, B3, D4, F#4
    const Dmaj7 = [146.83, 220.00, 277.18, 329.63]; // D3, A3, C#4, E4

    const sequence: any[] = [
        { notes: [98.00], duration: 1.5 }, // Low G2
        { notes: Gmaj7, duration: 1.5 },   // Chord
        { notes: Gmaj7, duration: 1.5 },   // Chord
        { notes: [73.42], duration: 1.5 }, // Low D2
        { notes: Dmaj7, duration: 1.5 },   // Chord
        { notes: Dmaj7, duration: 1.5 },   // Chord
    ];

    this.seqIndex = 0;
    const playNext = () => {
        if (!this.ambientType || !this.ctx) return;
        const step = sequence[this.seqIndex % sequence.length];
        this.seqIndex++;

        step.notes.forEach((freq: number) => {
            // Satie is softer, use sine/triangle mix
            this.triggerPianoNote(freq, 'sine', 0.15, 3.0);
        });

        this.ambientInterval = window.setTimeout(playNext, step.duration * 1000);
    };
    playNext();
  }

  private playJazzPiano() {
    // ii-V-I progressions with extensions
    const Dm9 = [293.66, 349.23, 415.30, 440.00, 523.25]; // D4, F4, G#4(b5), A4, C5
    const G13 = [196.00, 246.94, 329.63, 440.00]; 
    const Cmaj9 = [261.63, 329.63, 392.00, 493.88, 587.33];

    const chords = [Dm9, G13, Cmaj9];

    const playNext = () => {
        if (!this.ambientType || !this.ctx) return;

        // Randomly pick a chord
        const chord = chords[Math.floor(Math.random() * chords.length)];

        // Strum effect
        chord.forEach((freq, i) => {
            setTimeout(() => {
                this.triggerPianoNote(freq, 'triangle', 0.1, 1.5);
            }, i * 30); // 30ms strum delay
        });

        // Add a random high melody note occasionally
        if (Math.random() > 0.5) {
            setTimeout(() => {
                const scale = [523.25, 587.33, 659.25, 783.99, 880.00];
                const note = scale[Math.floor(Math.random() * scale.length)];
                this.triggerPianoNote(note, 'sine', 0.08, 1.0);
            }, 800);
        }

        const duration = 2000 + Math.random() * 2000;
        this.ambientInterval = window.setTimeout(playNext, duration);
    };
    playNext();
  }

  private triggerPianoNote(freq: number, type: OscillatorType = 'triangle', volume: number = 0.2, decay: number = 2.5) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);

    // Subtle detune for realism
    const osc2 = this.ctx.createOscillator();
    osc2.type = type;
    osc2.frequency.setValueAtTime(freq * 1.002, t);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(volume, t + 0.05);
    env.gain.exponentialRampToValueAtTime(0.001, t + decay);

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(800, t);
    filter.frequency.linearRampToValueAtTime(100, t + decay);

    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(env);

    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);

    osc.start(t);
    osc2.start(t);
    osc.stop(t + decay + 0.1);
    osc2.stop(t + decay + 0.1);

    setTimeout(() => { osc.disconnect(); osc2.disconnect(); env.disconnect(); filter.disconnect(); }, (decay + 0.2) * 1000);
  }

  // --- Guitar Generator ---

  private playAcousticGuitar() {
    const chords = [
        [196.00, 246.94, 293.66, 392.00], // G
        [164.81, 220.00, 261.63, 329.63], // C
        [146.83, 220.00, 293.66, 369.99], // D
        [130.81, 196.00, 261.63, 329.63]  // Em
    ];

    const playStrum = () => {
        if (!this.ambientType || !this.ctx) return;

        const chord = chords[Math.floor(Math.random() * chords.length)];

        // Arpeggiated finger picking pattern
        const pattern = [0, 2, 1, 3, 2, 1]; // string indices

        pattern.forEach((stringIdx, i) => {
            if (chord[stringIdx]) {
                const timeOffset = i * 250; // 8th notes at moderate tempo
                this.ambientInterval = window.setTimeout(() => {
                     this.triggerGuitarPluck(chord[stringIdx]);
                }, timeOffset);
            }
        });

        // Next bar
        this.ambientInterval = window.setTimeout(playStrum, 2000); // 1 bar duration roughly
    };
    playStrum();
  }

  private triggerGuitarPluck(freq: number) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth'; // Richer harmonics for strings
    osc.frequency.setValueAtTime(freq, t);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.15, t + 0.02); // Sharp attack
    env.gain.exponentialRampToValueAtTime(0.001, t + 1.5); // Short decay

    // Filter envelope to simulate string "twang" dying out
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.Q.value = 1;
    filter.frequency.setValueAtTime(3000, t);
    filter.frequency.exponentialRampToValueAtTime(100, t + 0.5);

    osc.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);

    osc.start(t);
    osc.stop(t + 1.5);
    setTimeout(() => { osc.disconnect(); env.disconnect(); filter.disconnect(); }, 1600);
  }

  // --- Cosmic Synth ---

  private playCosmicSynth() {
    const scale = [130.81, 155.56, 196.00, 233.08, 261.63]; // Cm pentatonic

    const playPad = () => {
        if (!this.ambientType || !this.ctx) return;
        const freq = scale[Math.floor(Math.random() * scale.length)];
        this.triggerSynthPad(freq);

        // Drone bass
        if (Math.random() > 0.7) this.triggerSynthPad(65.41, 6.0); // Low C

        const nextTime = 4000 + Math.random() * 4000;
        this.ambientInterval = window.setTimeout(playPad, nextTime);
    };
    playPad();
  }

  private triggerSynthPad(freq: number, duration: number = 8.0) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc1 = this.ctx.createOscillator();
    osc1.type = 'sawtooth';
    osc1.frequency.setValueAtTime(freq, t);

    const osc2 = this.ctx.createOscillator();
    osc2.type = 'square';
    osc2.frequency.setValueAtTime(freq * 1.01, t); // Detuned

    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.2; // Slow modulation
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 400;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 600;

    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.15, t + 2.0); // Slow attack
    env.gain.linearRampToValueAtTime(0, t + duration); // Long release

    osc1.connect(filter);
    osc2.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    // Heavy reverb via delay
    if (this.delayNode) {
        const send = this.ctx.createGain();
        send.gain.value = 0.6;
        env.connect(send);
        send.connect(this.delayNode);
    }

    osc1.start(t);
    osc2.start(t);
    lfo.start(t);
    osc1.stop(t + duration);
    osc2.stop(t + duration);
    lfo.stop(t + duration);

    setTimeout(() => { 
        osc1.disconnect(); osc2.disconnect(); lfo.disconnect(); env.disconnect(); 
    }, (duration + 1) * 1000);
  }

  // --- Hardcore Drums ---

  private playHardcoreDrums() {
    // 174 BPM approx
    const stepTime = 60 / 174 / 4; // 16th note duration

    let step = 0;
    const loop = () => {
        if (!this.ambientType || !this.ctx) return;

        const barStep = step % 16;

        // Kick Pattern (Amen-ish)
        if (barStep === 0 || barStep === 10) this.triggerKick();
        if (barStep === 2 && Math.random() > 0.5) this.triggerKick(0.5); // Ghost kick

        // Snare Pattern
        if (barStep === 4 || barStep === 12) this.triggerSnare();
        if (barStep === 15 && Math.random() > 0.7) this.triggerSnare(0.6); // Fill

        // Hi Hats (Fast)
        if (barStep % 2 === 0) this.triggerHat();
        if (Math.random() > 0.8) this.triggerHat(0.5); // Random shuffle

        step++;
        this.ambientInterval = window.setTimeout(loop, stepTime * 1000);
    };
    loop();
  }

  private triggerKick(vol: number = 1.0) {
    if (!this.ctx || !this.ambientGain || !this.masterGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.frequency.setValueAtTime(150, t);
    osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5);

    gain.gain.setValueAtTime(vol * 0.8, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);

    osc.connect(gain);
    gain.connect(this.ambientGain);

    osc.start(t);
    osc.stop(t + 0.5);
    setTimeout(() => { osc.disconnect(); gain.disconnect(); }, 600);
  }

  private triggerSnare(vol: number = 1.0) {
    if (!this.ctx || !this.ambientGain || !this.masterGain) return;
    const t = this.ctx.currentTime;

    // Reuse cached buffer if available
    if (!this.noiseBuffers['white']) this.generateNoiseBuffer('white', 1.0);
    const buffer = this.noiseBuffers['white'];

    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 1000;

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol * 0.5, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.2);

    // Add a 'tonal' pop for the snare body
    const osc = this.ctx.createOscillator();
    osc.frequency.setValueAtTime(250, t);
    osc.frequency.exponentialRampToValueAtTime(100, t + 0.1);
    const oscGain = this.ctx.createGain();
    oscGain.gain.setValueAtTime(vol * 0.5, t);
    oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.ambientGain);

    osc.connect(oscGain);
    oscGain.connect(this.ambientGain);

    noise.start(t);
    osc.start(t);
    noise.stop(t + 0.2);
    osc.stop(t + 0.2);

    setTimeout(() => { 
        noise.disconnect(); filter.disconnect(); gain.disconnect(); 
        osc.disconnect(); oscGain.disconnect();
    }, 300);
  }

  private triggerHat(vol: number = 1.0) {
    if (!this.ctx || !this.ambientGain || !this.masterGain) return;
    const t = this.ctx.currentTime;

    // Reuse cached buffer
    if (!this.noiseBuffers['white']) this.generateNoiseBuffer('white', 1.0);
    const buffer = this.noiseBuffers['white'];

    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 5000;

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol * 0.2, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.ambientGain);

    noise.start(t);
    noise.stop(t + 0.05);
    setTimeout(() => { noise.disconnect(); filter.disconnect(); gain.disconnect(); }, 100);
  }

  // --- Zen Bells ---
  private playProceduralZen() {
    const scale = [523.25, 587.33, 659.25, 783.99, 880.00]; // C major pentatonic

    const playNote = () => {
      if (!this.ctx || !this.ambientGain) return;
      const freq = scale[Math.floor(Math.random() * scale.length)];
      this.triggerBellNote(freq);
    };

    playNote();

    const scheduleNext = () => {
       if (!this.ambientType) return;
       const delay = 4000 + Math.random() * 4000;
       this.ambientInterval = window.setTimeout(() => {
          playNote();
          scheduleNext();
       }, delay);
    };
    scheduleNext();
  }

  private triggerBellNote(freq: number) {
    if (!this.ctx || !this.ambientGain || !this.masterGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);

    const modulator = this.ctx.createOscillator();
    modulator.type = 'sine';
    modulator.frequency.setValueAtTime(freq * 2.5, t); 
    const modGain = this.ctx.createGain();
    modGain.gain.setValueAtTime(freq * 0.5, t);
    modGain.gain.exponentialRampToValueAtTime(0.01, t + 2);

    modulator.connect(modGain);
    modGain.connect(osc.frequency);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.1, t + 0.02);
    env.gain.exponentialRampToValueAtTime(0.001, t + 4.0);

    osc.connect(env);
    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);

    osc.start(t);
    modulator.start(t);
    osc.stop(t + 4.0);
    modulator.stop(t + 4.0);

    setTimeout(() => {
        osc.disconnect();
        modulator.disconnect();
        env.disconnect();
    }, 4100);
  }

  // --- Global Helpers ---

  private runSequence(sequence: any[], playFn: (f: number) => void) {
    const playNextNote = () => {
        if (!this.ambientType || !this.ctx) return;
        const noteData = sequence[this.seqIndex % sequence.length];
        this.seqIndex++;
        playFn(noteData[0]);
        const duration = noteData[1] * 1000; 
        this.ambientInterval = window.setTimeout(playNextNote, duration);
    };
    this.seqIndex = 0;
    playNextNote();
  }

  public resumeContext() {
    this.ensureContext();
  }

  private ensureContext() {
    if (!this.ctx) return;
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    // Create master gain if it doesn't exist
    if (!this.masterGain) {
        this.masterGain = this.ctx.createGain();
        this.masterGain.gain.value = 1.0;
        this.masterGain.connect(this.ctx.destination);
    }
  }

  public playKeypress() {
     if (!this.enabled || !this.mechanicalEnabled || !this.ctx) return;
     this.ensureContext();
     if (!this.masterGain) return;

     switch(this.mechanicalPreset) {
         case 'CLICKY':
             this.playClicky();
             break;
         case 'BUBBLE':
             this.playBubble();
             break;
         case 'TYPEWRITER':
             this.playTypewriter();
             break;
         case 'THOCK':
         default:
             this.playThock();
             break;
     }
  }

  private playThock() {
     const t = this.ctx!.currentTime;

     // Deep Triangle
     const osc = this.ctx!.createOscillator();
     osc.type = 'triangle';
     osc.frequency.setValueAtTime(300 + Math.random()*50, t);
     osc.frequency.exponentialRampToValueAtTime(50, t + 0.08);

     const oscGain = this.ctx!.createGain();
     oscGain.gain.setValueAtTime(0.4, t);
     oscGain.gain.exponentialRampToValueAtTime(0.01, t + 0.08);

     osc.connect(oscGain);
     oscGain.connect(this.masterGain!);
     osc.start(t);
     osc.stop(t + 0.1);

     // Switch noise
     this.playFilteredNoise(t, 2000, 0.15, 0.05);
  }

  private playClicky() {
      const t = this.ctx!.currentTime;

      // High frequency pulse
      const osc = this.ctx!.createOscillator();
      osc.type = 'square';
      osc.frequency.setValueAtTime(1500, t);
      osc.frequency.exponentialRampToValueAtTime(500, t + 0.03);

      const oscGain = this.ctx!.createGain();
      oscGain.gain.setValueAtTime(0.1, t);
      oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.03);

      osc.connect(oscGain);
      oscGain.connect(this.masterGain!);
      osc.start(t);
      osc.stop(t + 0.04);

      // Crisper noise
      this.playFilteredNoise(t, 4000, 0.1, 0.04, 'highpass');
  }

  private playBubble() {
      const t = this.ctx!.currentTime;

      const osc = this.ctx!.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(600 + Math.random()*100, t);
      osc.frequency.exponentialRampToValueAtTime(100, t + 0.1);

      const oscGain = this.ctx!.createGain();
      oscGain.gain.setValueAtTime(0.3, t);
      oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

      osc.connect(oscGain);
      oscGain.connect(this.masterGain!);
      osc.start(t);
      osc.stop(t + 0.15);
  }

  private playTypewriter() {
      const t = this.ctx!.currentTime;

      // Metallic Ping
      const osc = this.ctx!.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(2000, t);
      const oscGain = this.ctx!.createGain();
      oscGain.gain.setValueAtTime(0.05, t);
      oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);

      osc.connect(oscGain);
      oscGain.connect(this.masterGain!);
      osc.start(t);
      osc.stop(t + 0.06);

      // Heavy Clack
      this.playFilteredNoise(t, 1200, 0.3, 0.05, 'lowpass');
  }

  private playFilteredNoise(t: number, freq: number, vol: number, dur: number, type: BiquadFilterType = 'lowpass') {
      if (!this.noiseBuffers['white']) this.generateNoiseBuffer('white', 1.0);
      const noise = this.ctx!.createBufferSource();
      noise.buffer = this.noiseBuffers['white'];

      const noiseFilter = this.ctx!.createBiquadFilter();
      noiseFilter.type = type;
      noiseFilter.frequency.setValueAtTime(freq, t);

      const noiseGain = this.ctx!.createGain();
      noiseGain.gain.setValueAtTime(vol, t);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, t + dur);

      noise.connect(noiseFilter);
      noiseFilter.connect(noiseGain);
      noiseGain.connect(this.masterGain!);
      noise.start(t);
      noise.stop(t + dur);
  }

  public playError() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    if (!this.masterGain) return;

    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, t);
    osc.frequency.linearRampToValueAtTime(100, t + 0.1);

    gain.gain.setValueAtTime(0.3, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.2);

    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(t);
    osc.stop(t + 0.2);
  }

  public playSuccess() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    if (!this.masterGain) return;
    const t = this.ctx.currentTime;

    [523.25, 659.25, 783.99].forEach((freq, i) => {
        const osc = this.ctx!.createOscillator();
        const gain = this.ctx!.createGain();

        osc.type = 'sine';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.05, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);

        osc.connect(gain);
        gain.connect(this.masterGain!);
        osc.start(t);
        osc.stop(t + 0.3);
    });
  }

  public playLevelUp() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    if (!this.masterGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(220, t);
    osc.frequency.exponentialRampToValueAtTime(880, t + 0.4);

    gain.gain.setValueAtTime(0.1, t);
    gain.gain.linearRampToValueAtTime(0, t + 0.4);

    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(t);
    osc.stop(t + 0.4);

    for(let i=0; i<6; i++) {
        setTimeout(() => {
            const spark = this.ctx!.createOscillator();
            const sgain = this.ctx!.createGain();
            spark.type = 'sine';
            spark.frequency.value = 880 + (i*200);
            sgain.gain.setValueAtTime(0.05, this.ctx!.currentTime);
            sgain.gain.exponentialRampToValueAtTime(0.001, this.ctx!.currentTime + 0.2);
            spark.connect(sgain);
            sgain.connect(this.masterGain!);
            spark.start();
            spark.stop(this.ctx!.currentTime + 0.2);
        }, i * 60);
    }
  }
}

export const soundEngine = new SoundEngine();

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { Quote, GameStatus, Settings, GameMode, WordPerformance } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { soundEngine } from '../utils/soundEngine';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Sparkles, ArrowUp, Lock, XCircle, AlertTriangle, ArrowRight, Eraser, Skull, FileText } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number, mistakes: string[], retryCount: number) => void;
  onFail: () => void;
  onMistake: (word?: string, expectedChar?: string, typedChar?: string) => void;
  onRequestNewQuote: () => void;
  onWordComplete?: (perf: WordPerformance) => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
  onInteract?: () => void;
  autoFocus?: boolean;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onWordComplete,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract,
  autoFocus = false
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(autoFocus);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);
  const [capsLock, setCapsLock] = useState(false);
  const [isShiftPressed, setIsShiftPressed] = useState(false);

  // Tracking Stats
  const [sessionMistakes, setSessionMistakes] = useState(0);
  const [sessionMistakeWords, setSessionMistakeWords] = useState<string[]>([]);
  const [retryCount, setRetryCount] = useState(0);

  // Word Timing State
  const wordStartTimeRef = useRef<number | null>(null);
  const currentWordIndexRef = useRef<number>(0);

  // Enhanced Error Tracking
  const [lastError, setLastError] = useState<{ 
      expectedChar: string, 
      typedChar: string, 
      index: number,
      expectedWord: string,
      typedWordPart: string 
  } | null>(null);

  // Smooth Caret State
  const [caretPos, setCaretPos] = useState({ left: 0, top: 0, height: 24, opacity: 0 });

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const textContainerRef = useRef<HTMLDivElement>(null);
  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const retryButtonRef = useRef<HTMLButtonElement>(null);

  // --- TTS LOGIC ---
  const speakText = useCallback((text: string) => {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.rate = 1.2; 
      window.speechSynthesis.speak(utterance);
  }, []);

  const triggerTTS = useCallback((index: number) => {
      if (settings.ttsMode === 'OFF') return;

      const words = quote.text.split(' ');

      if (settings.ttsMode === 'QUOTE') {
          if (index === 0) speakText(quote.text);
          return;
      }

      let textToSpeak = '';

      if (settings.ttsMode === 'WORD') {
          textToSpeak = words[index] || '';
      } else if (settings.ttsMode === 'FLOW') {
          const w1 = words[index] || '';
          const w2 = words[index + 1] || '';
          textToSpeak = `${w1} ${w2}`;
      } else if (settings.ttsMode === 'NEXT') {
          textToSpeak = words[index + 1] || '';
      } else if (settings.ttsMode === 'SCOUT') {
          textToSpeak = words[index + 2] || '';
      }

      if (textToSpeak.trim()) speakText(textToSpeak);
  }, [quote.text, settings.ttsMode, speakText]);

  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset]);

  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0);
    setSessionMistakeWords([]);
    setRetryCount(0);
    setLastError(null);
    wordStartTimeRef.current = null;
    currentWordIndexRef.current = 0;

    window.speechSynthesis.cancel();

    if (isFocused) {
        setTimeout(() => {
            inputRef.current?.focus();
        }, 10);
    }
  }, [quote]);

  useEffect(() => {
    if (status === GameStatus.COMPLETED) {
        setTimeout(() => nextButtonRef.current?.focus(), 50);
    } else if (status === GameStatus.FAILED) {
        setTimeout(() => retryButtonRef.current?.focus(), 50);
    }
  }, [status]);

  const handleRetry = useCallback(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0); 
    setLastError(null);
    setRetryCount(prev => prev + 1);
    wordStartTimeRef.current = null;
    currentWordIndexRef.current = 0;

    window.speechSynthesis.cancel();

    setIsFocused(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }, []);

  const handleNext = useCallback(() => {
    const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
    const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
    setIsFocused(true);
    onComplete(xp, wpm, sessionMistakeWords, retryCount);
  }, [onComplete, wpm, quote.text.length, streak, retryCount, sessionMistakes, sessionMistakeWords, settings.readAheadLevel]);

  useEffect(() => {
    const checkCapsLock = (e: KeyboardEvent | MouseEvent) => {
      if (e.getModifierState) {
        setCapsLock(e.getModifierState('CapsLock'));
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(true);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(false);
    };

    window.addEventListener('keydown', checkCapsLock as any);
    window.addEventListener('keyup', checkCapsLock as any);
    window.addEventListener('click', checkCapsLock as any);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', checkCapsLock as any);
      window.removeEventListener('keyup', checkCapsLock as any);
      window.removeEventListener('click', checkCapsLock as any);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (status === GameStatus.COMPLETED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      if (status === GameStatus.FAILED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (!isFocused) {
        if (e.key === 'Tab') return;

        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status, handleNext, handleRetry]);

  useLayoutEffect(() => {
    const updateCaret = () => {
        if (!textContainerRef.current) return;

        let targetEl: HTMLElement | null = null;
        let left = 0;
        let top = 0;
        let height = 0;

        if (input.length < quote.text.length) {
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            }
        } else {
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length - 1}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft + targetEl.offsetWidth;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            } else if (quote.text.length === 0) {
                 left = 0;
                 top = 0;
                 height = 24; 
            }
        }

        if (input.length === 0 && quote.text.length > 0) {
             const firstEl = textContainerRef.current.querySelector(`[data-index="0"]`) as HTMLElement;
             if (firstEl) {
                 left = firstEl.offsetLeft;
                 top = firstEl.offsetTop;
                 height = firstEl.offsetHeight;
             }
        }

        setCaretPos({ 
            left, 
            top, 
            height: height || 32, 
            opacity: isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED ? 1 : 0
        });
    };

    updateCaret();
    window.addEventListener('resize', updateCaret);
    return () => window.removeEventListener('resize', updateCaret);
  }, [input, quote, isFocused, status, settings.readAheadLevel]);

  const handleFocus = () => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;

    const val = e.target.value;
    const prevLen = input.length;
    const now = Date.now();

    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(now);
      setStatus(GameStatus.PLAYING);
      wordStartTimeRef.current = now;
    }

    if (val.length > prevLen) {
        soundEngine.playKeypress();
    }

    // --- WORD PERFORMANCE TRACKING ---
    if (val.endsWith(' ') && !input.endsWith(' ')) {
        const words = quote.text.split(' ');
        const finishedWord = words[currentWordIndexRef.current];
        if (finishedWord && wordStartTimeRef.current) {
            const wordDurationSec = (now - wordStartTimeRef.current) / 1000;
            const wordWpm = Math.round((finishedWord.length / 5) / (wordDurationSec / 60));

            if (onWordComplete) {
                onWordComplete({
                    word: finishedWord.toLowerCase().replace(/[^a-z]/g, ''),
                    wpm: wordWpm,
                    isCorrect: true
                });
            }
        }
        currentWordIndexRef.current += 1;
        wordStartTimeRef.current = now;

        const nextWordIndex = val.trim().split(' ').length;
        triggerTTS(nextWordIndex);
    }

    if (val.length > 0) {
      if (!quote.text.startsWith(val)) {
        soundEngine.playError();

        const mistakeIndex = val.length - 1;
        const expectedChar = quote.text[mistakeIndex];
        const typedChar = val[mistakeIndex];

        const wordStart = quote.text.lastIndexOf(' ', mistakeIndex) + 1;
        let wordEnd = quote.text.indexOf(' ', mistakeIndex);
        if (wordEnd === -1) wordEnd = quote.text.length;

        const expectedWord = quote.text.substring(wordStart, wordEnd);
        const typedWordPart = val.substring(wordStart);
        const cleanWord = expectedWord.replace(/[.,;!?]/g, '');

        setLastError({ 
            expectedChar, 
            typedChar, 
            index: mistakeIndex,
            expectedWord,
            typedWordPart
        });

        // Tracking the mistake for the mastery engine
        if (onWordComplete) {
            onWordComplete({
                word: cleanWord.toLowerCase().replace(/[^a-z]/g, ''),
                wpm: 0,
                isCorrect: false
            });
        }

        onMistake(cleanWord, expectedChar, typedChar);
        setSessionMistakes(prev => prev + 1);
        if (cleanWord && !sessionMistakeWords.includes(cleanWord)) {
            setSessionMistakeWords(prev => [...prev, cleanWord]);
        }

        if (gameMode === 'XQUOTES') {
            onFail(); 
            handleRetry(); 
            return;
        }

        setStatus(GameStatus.FAILED);
        onFail();
        return;
      }
    }

    setInput(val);

    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(now);

      if (isPerfect) {
        soundEngine.playSuccess(); 

        // Handle last word performance
        const words = quote.text.split(' ');
        const lastWord = words[words.length - 1];
        if (lastWord && wordStartTimeRef.current) {
            const wordDurationSec = (now - wordStartTimeRef.current) / 1000;
            const wordWpm = Math.round((lastWord.length / 5) / (wordDurationSec / 60));
            if (onWordComplete) {
                onWordComplete({
                    word: lastWord.toLowerCase().replace(/[^a-z]/g, ''),
                    wpm: wordWpm,
                    isCorrect: true
                });
            }
        }

        if (gameMode === 'XQUOTES') {
            const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
            const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
            onComplete(xp, wpm, sessionMistakeWords, retryCount);
            return;
        }

        setStatus(GameStatus.COMPLETED);
        const finalTime = now;
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        soundEngine.playError();
        if (gameMode === 'XQUOTES') {
            onFail();
            handleRetry();
            return;
        } 
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const getReadAheadState = (index: number) => {
    if (settings.readAheadLevel === 'NONE' || status === GameStatus.IDLE) return { isHidden: false, isHighlighted: false };

    const text = quote.text;
    const caret = input.length;

    let currentWordStart = text.lastIndexOf(' ', caret - 1);
    currentWordStart = currentWordStart === -1 ? 0 : currentWordStart + 1;

    let currentWordEnd = text.indexOf(' ', caret);
    if (currentWordEnd === -1) currentWordEnd = text.length;

    if (index >= currentWordStart && index < currentWordEnd) {
        return { isHidden: true, isHighlighted: false };
    }

    if (settings.readAheadLevel === 'ULTRA' || settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        if (index >= nextWordStart && index < nextWordEnd) {
            return { isHidden: true, isHighlighted: false }; 
        }
    }

    if (settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        let secondNextStart = nextWordEnd + 1;
        let secondNextEnd = text.indexOf(' ', secondNextStart);
        if (secondNextEnd === -1) secondNextEnd = text.length;

        if (index >= secondNextStart && index < secondNextEnd) {
             return { isHidden: true, isHighlighted: false };
        }
    }

    if (index > currentWordEnd) { 
        let highlightStart = currentWordEnd + 1;
        if (settings.readAheadLevel === 'ULTRA') {
             let skip1 = text.indexOf(' ', highlightStart);
             if (skip1 !== -1) highlightStart = skip1 + 1;
             else highlightStart = text.length; 
        } else if (settings.readAheadLevel === 'BLIND') {
             let skip1 = text.indexOf(' ', highlightStart);
             let skip2 = skip1 !== -1 ? text.indexOf(' ', skip1 + 1) : -1;
             if (skip2 !== -1) highlightStart = skip2 + 1;
             else highlightStart = text.length;
        }

        let highlightEnd = text.indexOf(' ', highlightStart);
        if (highlightEnd === -1) highlightEnd = text.length;

        if (index >= highlightStart && index < highlightEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const getTextColor = () => {
     if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') return 'text-red-400/50';
        return 'text-red-300';
     }
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = getTextColor(); 
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-green'; 
        } else {
          colorClass = 'text-red-500 bg-red-100'; 
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-green font-bold';
              bgClass = 'bg-green-100/50';
          }
      }

      if (gameMode === 'XWORDS' || gameMode === 'XQUOTES') {
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} data-index={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}

            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') {
            return 'bg-red-900/20 border-red-900/50 shadow-[0_0_40px_rgba(220,38,38,0.1)]';
        }
        return 'bg-red-50 border-red-200 shadow-inner';
    }

    if (gameMode === 'HARDCORE') {
        return 'bg-neutral-900 border-neutral-800 text-neutral-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'XWORDS' || gameMode === 'XQUOTES') {
        return 'bg-red-50 border-red-100';
    }

    return 'bg-stone-50 border-stone-200 overflow-hidden';
  };

  const getFontSizeClass = () => {
    const len = quote.text.length;
    if (len < 100) return 'text-xl md:text-2xl leading-relaxed';
    if (len < 200) return 'text-lg md:text-xl leading-relaxed';
    return 'text-base md:text-lg leading-relaxed';
  };

  const isPerfectMasterPotential = retryCount === 0 && sessionMistakes === 0;

  const getCompletionContent = () => {
      switch(gameMode) {
          case 'XWORDS':
              return { title: 'Correction Complete!', btnLabel: 'Next Batch', Icon: Eraser };
          case 'PRACTICE':
              return { title: 'Words Mastered!', btnLabel: 'More Words', Icon: FileText };
          case 'HARDCORE':
              return { title: 'Survival Successful!', btnLabel: 'Next Challenge', Icon: Skull };
          case 'XQUOTES':
              return { title: 'Redemption!', btnLabel: 'Continue', Icon: RotateCcw };
          default:
              return { title: 'Quote Complete!', btnLabel: 'Next Quote', Icon: Award };
      }
  };

  const { title: completionTitle, btnLabel: completionBtn, Icon: CompletionIcon } = getCompletionContent();

  return (
    <div className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col" ref={containerRef}>
      {isPerfectMasterPotential && status === GameStatus.PLAYING && (
        <div className="absolute -top-8 left-1/2 transform -translate-x-1/2 flex items-center gap-1 text-xs font-bold text-frog-green animate-pulse">
          <Sparkles className="w-3 h-3" /> Perfect Master Potential (1.5x Bonus)
        </div>
      )}

      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-16 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${isFocused && status !== GameStatus.FAILED && status !== GameStatus.COMPLETED ? 'ring-2 ring-frog-green/50 ring-offset-2 ring-offset-bg-body' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-green/20 bg-green-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && (
          <div 
            onClick={handleFocus}
            className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-sm cursor-pointer rounded-[3rem] border-2 border-dashed border-frog-green/50 hover:border-frog-green transition-all"
          >
            <div className="text-center animate-bounce text-frog-green">
              <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
              <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
            </div>
          </div>
        )}

        {status === GameStatus.COMPLETED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center bg-stone-900/10 backdrop-blur-sm rounded-[3rem] cursor-pointer" onClick={handleNext}>
             <div className="bg-stone-50/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-stone-200 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-6 min-w-[280px] cursor-default" onClick={(e) => e.stopPropagation()}>
                <div className="text-frog-green font-black text-xl tracking-tight flex items-center gap-2">
                   <CompletionIcon className="w-6 h-6" /> {completionTitle}
                </div>
                <div className="grid grid-cols-2 gap-x-12 gap-y-6 w-full">
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Time</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{endTime && startTime ? ((endTime - startTime) / 1000).toFixed(1) : '0.0'}s</span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Speed</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{wpm} <span className="text-xs text-stone-400 font-sans font-medium">WPM</span></span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Retries</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{retryCount}</span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">XP Earned</span>
                      <span className="font-mono font-bold text-2xl text-frog-green">+{calculateXP(wpm, quote.text.length, streak, retryCount === 0 && sessionMistakes === 0, settings.readAheadLevel) * (gameMode === 'HARDCORE' ? 5 : 1)}</span>
                   </div>
                </div>
                <button ref={nextButtonRef} onClick={handleNext} className="flex items-center gap-2 px-8 py-3 rounded-full transition shadow-lg font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-offset-2 w-full justify-center bg-frog-green text-white hover:bg-green-500 shadow-green-200/50 focus:ring-frog-green">
                   {completionBtn} <CompletionIcon className="w-4 h-4" />
                </button>
             </div>
          </div>
        )}

        {status === GameStatus.FAILED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center bg-stone-900/10 backdrop-blur-sm rounded-[3rem] cursor-pointer" onClick={handleRetry}>
             <div className="bg-white p-6 rounded-3xl shadow-2xl border border-stone-100 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-4 min-w-[260px] cursor-default" onClick={(e) => e.stopPropagation()}>
                <div className="text-red-500 font-black text-xl tracking-tight flex items-center gap-2">
                   <XCircle className="w-6 h-6" /> Run Failed
                </div>
                <div className="w-full bg-red-50 p-3 rounded-xl border border-red-100 flex flex-col items-center gap-1">
                    {lastError ? (
                        <>
                            <div className="text-[10px] font-bold text-red-400 uppercase tracking-wider">Mistake</div>
                            <div className="flex items-center gap-3 font-mono text-base">
                                 <span className="text-red-500 font-medium" title="You Typed">{lastError.typedWordPart}</span>
                                 <ArrowRight className="w-3.5 h-3.5 text-stone-300" />
                                 <span className="text-frog-green font-bold" title="Expected">{lastError.expectedWord}</span>
                            </div>
                        </>
                    ) : (
                        <span className="text-stone-400 italic text-xs">Unknown Error</span>
                    )}
                </div>
                <div className="flex w-full justify-between gap-4 px-2">
                     <div className="flex flex-col items-center">
                        <span className="text-[9px] uppercase font-bold text-stone-400 tracking-wider">Progress</span>
                        <span className="font-mono font-bold text-lg text-stone-700">{Math.floor((input.length / quote.text.length) * 100)}%</span>
                     </div>
                     <div className="w-px bg-stone-100"></div>
                     <div className="flex flex-col items-center">
                        <span className="text-[9px] uppercase font-bold text-stone-400 tracking-wider">Speed</span>
                        <span className="font-mono font-bold text-lg text-stone-700">{wpm}</span>
                     </div>
                </div>
                <button ref={retryButtonRef} onClick={handleRetry} className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-red-500 text-white hover:bg-red-600 rounded-xl transition shadow-lg shadow-red-200/50 font-bold text-xs tracking-wide uppercase focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 transform hover:-translate-y-0.5">
                  <RotateCcw className="w-3.5 h-3.5" /> Try Again
                </button>
             </div>
          </div>
        )}

        <div className="absolute top-4 left-0 right-0 flex justify-center gap-2 z-30 select-none pointer-events-none">
            {capsLock && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-100 text-orange-600 rounded-full text-[10px] font-bold tracking-widest border border-orange-200 shadow-sm animate-pulse">
                <Lock className="w-3 h-3" /> CAPS LOCK
              </div>
            )}
            {isShiftPressed && (
               <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-[10px] font-bold tracking-widest border border-blue-100 shadow-sm">
                <ArrowUp className="w-3 h-3" /> SHIFT
              </div>
            )}
        </div>

        <div className="absolute top-10 left-0 right-0 px-10 md:px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans z-10 text-stone-500">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3.5 h-3.5"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadLevel !== 'NONE' && <span className="text-frog-green flex items-center gap-1"><EyeOff className="w-3.5 h-3.5"/> {settings.readAheadLevel}</span>}
          </div>
          <span className="text-right max-w-[200px] truncate">{quote.author}</span>
        </div>

        <div ref={textContainerRef} className={`font-mono tracking-wide break-words whitespace-pre-wrap mb-12 mt-10 relative z-10 outline-none select-none ${getTextColor()} ${getFontSizeClass()}`} onClick={handleFocus}>
          <div className="absolute bg-frog-green w-[3px] rounded-full transition-all duration-100 ease-out z-20 pointer-events-none caret-blink shadow-[0_0_10px_rgba(64,214,114,0.5)]"
             style={{ left: caretPos.left - 1, top: caretPos.top + 2, height: caretPos.height - 4, opacity: caretPos.opacity }}
          />
          {renderText()}
        </div>

        <textarea ref={inputRef} value={input} onChange={handleChange} onBlur={handleBlur} onFocus={() => { setIsFocused(true); onInteract?.(); if (status === GameStatus.IDLE && input.length === 0) triggerTTS(0); }}
          onKeyDown={(e) => { if (e.key === 'Enter') e.preventDefault(); }} onPaste={(e) => e.preventDefault()} onCopy={(e) => e.preventDefault()} onDrop={(e) => e.preventDefault()}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none" autoFocus={isFocused} disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        <div className="absolute bottom-10 left-0 right-0 px-10 md:px-20 flex justify-between items-end select-none z-10">
           <div className="flex items-center gap-10 text-stone-400 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-xl opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-xl flex items-center gap-1.5 font-sans">
                        <Flame className={`w-4 h-4 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>
        </div>
      </div>

      <div className="text-center mt-8 h-4 text-stone-400 text-xs font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? <span className="text-red-400">{gameMode === 'HARDCORE' ? 'HARDCORE FAIL. 50% XP Penalty.' : 'Mistake made. Review your error above.'}</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-green">Perfect! Streak +1 {retryCount === 0 && sessionMistakes === 0 && "(Mastery Bonus!)"}</span> :
         isFocused ? "Accuracy is paramount. One mistake restarts the quote." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { Quote, GameStatus, Settings, GameMode, WordPerformance } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { soundEngine } from '../utils/soundEngine';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Sparkles, ArrowUp, Lock, XCircle, AlertTriangle, ArrowRight, Eraser, Skull, FileText } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number, mistakes: string[], retryCount: number) => void;
  onFail: () => void;
  onMistake: (word?: string, expectedChar?: string, typedChar?: string) => void;
  onRequestNewQuote: () => void;
  onWordComplete?: (perf: WordPerformance) => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
  onInteract?: () => void;
  autoFocus?: boolean;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onWordComplete,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract,
  autoFocus = false
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(autoFocus);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);
  const [capsLock, setCapsLock] = useState(false);
  const [isShiftPressed, setIsShiftPressed] = useState(false);

  // Tracking Stats
  const [sessionMistakes, setSessionMistakes] = useState(0);
  const [sessionMistakeWords, setSessionMistakeWords] = useState<string[]>([]);
  const [retryCount, setRetryCount] = useState(0);

  // Word Timing State
  const wordStartTimeRef = useRef<number | null>(null);
  const currentWordIndexRef = useRef<number>(0);

  // Enhanced Error Tracking
  const [lastError, setLastError] = useState<{ 
      expectedChar: string, 
      typedChar: string, 
      index: number,
      expectedWord: string,
      typedWordPart: string 
  } | null>(null);

  // Smooth Caret State
  const [caretPos, setCaretPos] = useState({ left: 0, top: 0, height: 24, opacity: 0 });

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const textContainerRef = useRef<HTMLDivElement>(null);
  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const retryButtonRef = useRef<HTMLButtonElement>(null);

  // --- TTS LOGIC ---
  const speakText = useCallback((text: string) => {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.rate = 1.2; 
      window.speechSynthesis.speak(utterance);
  }, []);

  const triggerTTS = useCallback((index: number) => {
      if (settings.ttsMode === 'OFF') return;

      const words = quote.text.split(' ');

      if (settings.ttsMode === 'QUOTE') {
          if (index === 0) speakText(quote.text);
          return;
      }

      let textToSpeak = '';

      if (settings.ttsMode === 'WORD') {
          textToSpeak = words[index] || '';
      } else if (settings.ttsMode === 'FLOW') {
          const w1 = words[index] || '';
          const w2 = words[index + 1] || '';
          textToSpeak = `${w1} ${w2}`;
      } else if (settings.ttsMode === 'NEXT') {
          textToSpeak = words[index + 1] || '';
      } else if (settings.ttsMode === 'SCOUT') {
          textToSpeak = words[index + 2] || '';
      }

      if (textToSpeak.trim()) speakText(textToSpeak);
  }, [quote.text, settings.ttsMode, speakText]);

  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset]);

  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0);
    setSessionMistakeWords([]);
    setRetryCount(0);
    setLastError(null);
    wordStartTimeRef.current = null;
    currentWordIndexRef.current = 0;

    window.speechSynthesis.cancel();

    if (isFocused) {
        setTimeout(() => {
            inputRef.current?.focus();
        }, 10);
    }
  }, [quote]);

  useEffect(() => {
    if (status === GameStatus.COMPLETED) {
        setTimeout(() => nextButtonRef.current?.focus(), 50);
    } else if (status === GameStatus.FAILED) {
        setTimeout(() => retryButtonRef.current?.focus(), 50);
    }
  }, [status]);

  const handleRetry = useCallback(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0); 
    setLastError(null);
    setRetryCount(prev => prev + 1);
    wordStartTimeRef.current = null;
    currentWordIndexRef.current = 0;

    window.speechSynthesis.cancel();

    setIsFocused(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }, []);

  const handleNext = useCallback(() => {
    const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
    const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
    setIsFocused(true);
    onComplete(xp, wpm, sessionMistakeWords, retryCount);
  }, [onComplete, wpm, quote.text.length, streak, retryCount, sessionMistakes, sessionMistakeWords, settings.readAheadLevel]);

  useEffect(() => {
    const checkCapsLock = (e: KeyboardEvent | MouseEvent) => {
      if (e.getModifierState) {
        setCapsLock(e.getModifierState('CapsLock'));
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(true);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(false);
    };

    window.addEventListener('keydown', checkCapsLock as any);
    window.addEventListener('keyup', checkCapsLock as any);
    window.addEventListener('click', checkCapsLock as any);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', checkCapsLock as any);
      window.removeEventListener('keyup', checkCapsLock as any);
      window.removeEventListener('click', checkCapsLock as any);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (status === GameStatus.COMPLETED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      if (status === GameStatus.FAILED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (!isFocused) {
        if (e.key === 'Tab') return;

        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status, handleNext, handleRetry]);

  useLayoutEffect(() => {
    const updateCaret = () => {
        if (!textContainerRef.current) return;

        let targetEl: HTMLElement | null = null;
        let left = 0;
        let top = 0;
        let height = 0;

        if (input.length < quote.text.length) {
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            }
        } else {
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length - 1}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft + targetEl.offsetWidth;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            } else if (quote.text.length === 0) {
                 left = 0;
                 top = 0;
                 height = 24; 
            }
        }

        if (input.length === 0 && quote.text.length > 0) {
             const firstEl = textContainerRef.current.querySelector(`[data-index="0"]`) as HTMLElement;
             if (firstEl) {
                 left = firstEl.offsetLeft;
                 top = firstEl.offsetTop;
                 height = firstEl.offsetHeight;
             }
        }

        setCaretPos({ 
            left, 
            top, 
            height: height || 32, 
            opacity: isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED ? 1 : 0
        });
    };

    updateCaret();
    window.addEventListener('resize', updateCaret);
    return () => window.removeEventListener('resize', updateCaret);
  }, [input, quote, isFocused, status, settings.readAheadLevel]);

  const handleFocus = () => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;

    const val = e.target.value;
    const prevLen = input.length;
    const now = Date.now();

    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(now);
      setStatus(GameStatus.PLAYING);
      wordStartTimeRef.current = now;
    }

    if (val.length > prevLen) {
        soundEngine.playKeypress();
    }

    // --- WORD PERFORMANCE TRACKING ---
    if (val.endsWith(' ') && !input.endsWith(' ')) {
        const words = quote.text.split(' ');
        const finishedWord = words[currentWordIndexRef.current];
        if (finishedWord && wordStartTimeRef.current) {
            const wordDurationSec = (now - wordStartTimeRef.current) / 1000;
            const wordWpm = Math.round((finishedWord.length / 5) / (wordDurationSec / 60));

            if (onWordComplete) {
                onWordComplete({
                    word: finishedWord.toLowerCase().replace(/[^a-z]/g, ''),
                    wpm: wordWpm,
                    isCorrect: true
                });
            }
        }
        currentWordIndexRef.current += 1;
        wordStartTimeRef.current = now;

        const nextWordIndex = val.trim().split(' ').length;
        triggerTTS(nextWordIndex);
    }

    if (val.length > 0) {
      if (!quote.text.startsWith(val)) {
        soundEngine.playError();

        const mistakeIndex = val.length - 1;
        const expectedChar = quote.text[mistakeIndex];
        const typedChar = val[mistakeIndex];

        const wordStart = quote.text.lastIndexOf(' ', mistakeIndex) + 1;
        let wordEnd = quote.text.indexOf(' ', mistakeIndex);
        if (wordEnd === -1) wordEnd = quote.text.length;

        const expectedWord = quote.text.substring(wordStart, wordEnd);
        const typedWordPart = val.substring(wordStart);
        const cleanWord = expectedWord.replace(/[.,;!?]/g, '');

        setLastError({ 
            expectedChar, 
            typedChar, 
            index: mistakeIndex,
            expectedWord,
            typedWordPart
        });

        // Tracking the mistake for the mastery engine
        if (onWordComplete) {
            onWordComplete({
                word: cleanWord.toLowerCase().replace(/[^a-z]/g, ''),
                wpm: 0,
                isCorrect: false
            });
        }

        onMistake(cleanWord, expectedChar, typedChar);
        setSessionMistakes(prev => prev + 1);
        if (cleanWord && !sessionMistakeWords.includes(cleanWord)) {
            setSessionMistakeWords(prev => [...prev, cleanWord]);
        }

        if (gameMode === 'XQUOTES') {
            onFail(); 
            handleRetry(); 
            return;
        }

        setStatus(GameStatus.FAILED);
        onFail();
        return;
      }
    }

    setInput(val);

    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(now);

      if (isPerfect) {
        soundEngine.playSuccess(); 

        // Handle last word performance
        const words = quote.text.split(' ');
        const lastWord = words[words.length - 1];
        if (lastWord && wordStartTimeRef.current) {
            const wordDurationSec = (now - wordStartTimeRef.current) / 1000;
            const wordWpm = Math.round((lastWord.length / 5) / (wordDurationSec / 60));
            if (onWordComplete) {
                onWordComplete({
                    word: lastWord.toLowerCase().replace(/[^a-z]/g, ''),
                    wpm: wordWpm,
                    isCorrect: true
                });
            }
        }

        if (gameMode === 'XQUOTES') {
            const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
            const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
            onComplete(xp, wpm, sessionMistakeWords, retryCount);
            return;
        }

        setStatus(GameStatus.COMPLETED);
        const finalTime = now;
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        soundEngine.playError();
        if (gameMode === 'XQUOTES') {
            onFail();
            handleRetry();
            return;
        } 
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const getReadAheadState = (index: number) => {
    if (settings.readAheadLevel === 'NONE' || status === GameStatus.IDLE) return { isHidden: false, isHighlighted: false };

    const text = quote.text;
    const caret = input.length;

    let currentWordStart = text.lastIndexOf(' ', caret - 1);
    currentWordStart = currentWordStart === -1 ? 0 : currentWordStart + 1;

    let currentWordEnd = text.indexOf(' ', caret);
    if (currentWordEnd === -1) currentWordEnd = text.length;

    if (index >= currentWordStart && index < currentWordEnd) {
        return { isHidden: true, isHighlighted: false };
    }

    if (settings.readAheadLevel === 'ULTRA' || settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        if (index >= nextWordStart && index < nextWordEnd) {
            return { isHidden: true, isHighlighted: false }; 
        }
    }

    if (settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        let secondNextStart = nextWordEnd + 1;
        let secondNextEnd = text.indexOf(' ', secondNextStart);
        if (secondNextEnd === -1) secondNextEnd = text.length;

        if (index >= secondNextStart && index < secondNextEnd) {
             return { isHidden: true, isHighlighted: false };
        }
    }

    if (index > currentWordEnd) { 
        let highlightStart = currentWordEnd + 1;
        if (settings.readAheadLevel === 'ULTRA') {
             let skip1 = text.indexOf(' ', highlightStart);
             if (skip1 !== -1) highlightStart = skip1 + 1;
             else highlightStart = text.length; 
        } else if (settings.readAheadLevel === 'BLIND') {
             let skip1 = text.indexOf(' ', highlightStart);
             let skip2 = skip1 !== -1 ? text.indexOf(' ', skip1 + 1) : -1;
             if (skip2 !== -1) highlightStart = skip2 + 1;
             else highlightStart = text.length;
        }

        let highlightEnd = text.indexOf(' ', highlightStart);
        if (highlightEnd === -1) highlightEnd = text.length;

        if (index >= highlightStart && index < highlightEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const getTextColor = () => {
     if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') return 'text-red-400/50';
        return 'text-red-300';
     }
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = getTextColor(); 
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-500'; // Changed from frog-green to frog-500 for theming
        } else {
          colorClass = 'text-red-500 bg-red-100'; 
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-500 font-bold'; // Changed for theming
              bgClass = 'bg-frog-200/20'; // Use themed highlight
          }
      }

      if (gameMode === 'XWORDS' || gameMode === 'XQUOTES') {
          if (index >= input.length) {
              colorClass = 'text-stone-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} data-index={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}

            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') {
            return 'bg-red-900/20 border-red-900/50 shadow-[0_0_40px_rgba(220,38,38,0.1)]';
        }
        return 'bg-red-50 border-red-200 shadow-inner';
    }

    if (gameMode === 'HARDCORE') {
        return 'bg-stone-900 border-stone-800 text-stone-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'XWORDS' || gameMode === 'XQUOTES') {
        return 'bg-red-50 border-red-100';
    }

    return 'bg-stone-50 border-stone-200 overflow-hidden';
  };

  const getFontSizeClass = () => {
    const len = quote.text.length;
    if (len < 100) return 'text-xl md:text-2xl leading-relaxed';
    if (len < 200) return 'text-lg md:text-xl leading-relaxed';
    return 'text-base md:text-lg leading-relaxed';
  };

  const isPerfectMasterPotential = retryCount === 0 && sessionMistakes === 0;

  const getCompletionContent = () => {
      switch(gameMode) {
          case 'XWORDS':
              return { title: 'Correction Complete!', btnLabel: 'Next Batch', Icon: Eraser };
          case 'PRACTICE':
              return { title: 'Words Mastered!', btnLabel: 'More Words', Icon: FileText };
          case 'HARDCORE':
              return { title: 'Survival Successful!', btnLabel: 'Next Challenge', Icon: Skull };
          case 'XQUOTES':
              return { title: 'Redemption!', btnLabel: 'Continue', Icon: RotateCcw };
          default:
              return { title: 'Quote Complete!', btnLabel: 'Next Quote', Icon: Award };
      }
  };

  const { title: completionTitle, btnLabel: completionBtn, Icon: CompletionIcon } = getCompletionContent();

  return (
    <div className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col" ref={containerRef}>
      {isPerfectMasterPotential && status === GameStatus.PLAYING && (
        <div className="absolute -top-8 left-1/2 transform -translate-x-1/2 flex items-center gap-1 text-xs font-bold text-frog-500 animate-pulse">
          <Sparkles className="w-3 h-3" /> Perfect Master Potential (1.5x Bonus)
        </div>
      )}

      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-16 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${isFocused && status !== GameStatus.FAILED && status !== GameStatus.COMPLETED ? 'ring-2 ring-frog-500/50 ring-offset-2 ring-offset-bg-body' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-500/20 bg-frog-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && (
          <div 
            onClick={handleFocus}
            className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-sm cursor-pointer rounded-[3rem] border-2 border-dashed border-frog-500/50 hover:border-frog-500 transition-all"
          >
            <div className="text-center animate-bounce text-frog-500">
              <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
              <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
            </div>
          </div>
        )}

        {status === GameStatus.COMPLETED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center bg-stone-900/10 backdrop-blur-sm rounded-[3rem] cursor-pointer" onClick={handleNext}>
             <div className="bg-stone-50/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-stone-200 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-6 min-w-[280px] cursor-default" onClick={(e) => e.stopPropagation()}>
                <div className="text-frog-500 font-black text-xl tracking-tight flex items-center gap-2">
                   <CompletionIcon className="w-6 h-6" /> {completionTitle}
                </div>
                <div className="grid grid-cols-2 gap-x-12 gap-y-6 w-full">
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Time</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{endTime && startTime ? ((endTime - startTime) / 1000).toFixed(1) : '0.0'}s</span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Speed</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{wpm} <span className="text-xs text-stone-400 font-sans font-medium">WPM</span></span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Retries</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{retryCount}</span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">XP Earned</span>
                      <span className="font-mono font-bold text-2xl text-frog-500">+{calculateXP(wpm, quote.text.length, streak, retryCount === 0 && sessionMistakes === 0, settings.readAheadLevel) * (gameMode === 'HARDCORE' ? 5 : 1)}</span>
                   </div>
                </div>
                <button ref={nextButtonRef} onClick={handleNext} className="flex items-center gap-2 px-8 py-3 rounded-full transition shadow-lg font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-offset-2 w-full justify-center bg-frog-500 text-white hover:opacity-90 shadow-frog-200/50 focus:ring-frog-500">
                   {completionBtn} <CompletionIcon className="w-4 h-4" />
                </button>
             </div>
          </div>
        )}

        {status === GameStatus.FAILED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center bg-stone-900/10 backdrop-blur-sm rounded-[3rem] cursor-pointer" onClick={handleRetry}>
             <div className="bg-white p-6 rounded-3xl shadow-2xl border border-stone-100 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-4 min-w-[260px] cursor-default" onClick={(e) => e.stopPropagation()}>
                <div className="text-red-500 font-black text-xl tracking-tight flex items-center gap-2">
                   <XCircle className="w-6 h-6" /> Run Failed
                </div>
                <div className="w-full bg-red-50 p-3 rounded-xl border border-red-100 flex flex-col items-center gap-1">
                    {lastError ? (
                        <>
                            <div className="text-[10px] font-bold text-red-400 uppercase tracking-wider">Mistake</div>
                            <div className="flex items-center gap-3 font-mono text-base">
                                 <span className="text-red-500 font-medium" title="You Typed">{lastError.typedWordPart}</span>
                                 <ArrowRight className="w-3.5 h-3.5 text-stone-300" />
                                 <span className="text-frog-500 font-bold" title="Expected">{lastError.expectedWord}</span>
                            </div>
                        </>
                    ) : (
                        <span className="text-stone-400 italic text-xs">Unknown Error</span>
                    )}
                </div>
                <div className="flex w-full justify-between gap-4 px-2">
                     <div className="flex flex-col items-center">
                        <span className="text-[9px] uppercase font-bold text-stone-400 tracking-wider">Progress</span>
                        <span className="font-mono font-bold text-lg text-stone-700">{Math.floor((input.length / quote.text.length) * 100)}%</span>
                     </div>
                     <div className="w-px bg-stone-100"></div>
                     <div className="flex flex-col items-center">
                        <span className="text-[9px] uppercase font-bold text-stone-400 tracking-wider">Speed</span>
                        <span className="font-mono font-bold text-lg text-stone-700">{wpm}</span>
                     </div>
                </div>
                <button ref={retryButtonRef} onClick={handleRetry} className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-red-500 text-white hover:bg-red-600 rounded-xl transition shadow-lg shadow-red-200/50 font-bold text-xs tracking-wide uppercase focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 transform hover:-translate-y-0.5">
                  <RotateCcw className="w-3.5 h-3.5" /> Try Again
                </button>
             </div>
          </div>
        )}

        <div className="absolute top-4 left-0 right-0 flex justify-center gap-2 z-30 select-none pointer-events-none">
            {capsLock && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-100 text-orange-600 rounded-full text-[10px] font-bold tracking-widest border border-orange-200 shadow-sm animate-pulse">
                <Lock className="w-3 h-3" /> CAPS LOCK
              </div>
            )}
            {isShiftPressed && (
               <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-[10px] font-bold tracking-widest border border-blue-100 shadow-sm">
                <ArrowUp className="w-3 h-3" /> SHIFT
              </div>
            )}
        </div>

        <div className="absolute top-10 left-0 right-0 px-10 md:px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans z-10 text-stone-500">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3.5 h-3.5"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadLevel !== 'NONE' && <span className="text-frog-500 flex items-center gap-1"><EyeOff className="w-3.5 h-3.5"/> {settings.readAheadLevel}</span>}
          </div>
          <span className="text-right max-w-[200px] truncate">{quote.author}</span>
        </div>

        <div ref={textContainerRef} className={`font-mono tracking-wide break-words whitespace-pre-wrap mb-12 mt-10 relative z-10 outline-none select-none ${getTextColor()} ${getFontSizeClass()}`} onClick={handleFocus}>
          <div className="absolute bg-frog-500 w-[3px] rounded-full transition-all duration-100 ease-out z-20 pointer-events-none caret-blink shadow-[0_0_10px_rgba(64,214,114,0.5)]"
             style={{ left: caretPos.left - 1, top: caretPos.top + 2, height: caretPos.height - 4, opacity: caretPos.opacity }}
          />
          {renderText()}
        </div>

        <textarea ref={inputRef} value={input} onChange={handleChange} onBlur={handleBlur} onFocus={() => { setIsFocused(true); onInteract?.(); if (status === GameStatus.IDLE && input.length === 0) triggerTTS(0); }}
          onKeyDown={(e) => { if (e.key === 'Enter') e.preventDefault(); }} onPaste={(e) => e.preventDefault()} onCopy={(e) => e.preventDefault()} onDrop={(e) => e.preventDefault()}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none" autoFocus={isFocused} disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        <div className="absolute bottom-10 left-0 right-0 px-10 md:px-20 flex justify-between items-end select-none z-10">
           <div className="flex items-center gap-10 text-stone-400 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-xl opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-xl flex items-center gap-1.5 font-sans">
                        <Flame className={`w-4 h-4 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>
        </div>
      </div>

      <div className="text-center mt-8 h-4 text-stone-400 text-xs font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? <span className="text-red-400">{gameMode === 'HARDCORE' ? 'HARDCORE FAIL. 50% XP Penalty.' : 'Mistake made. Review your error above.'}</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-500">Perfect! Streak +1 {retryCount === 0 && sessionMistakes === 0 && "(Mastery Bonus!)"}</span> :
         isFocused ? "Accuracy is paramount. One mistake restarts the quote." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import MiniGameMenu from './components/MiniGameMenu';
import TenFastGame from './components/BlitzGame';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, StrictRemediation, WordDrill, WordPerformance } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getAverageWPM, LEVELS } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, Skull, BookOpen, Eraser, Palette, Brain, Zap, Lock, RotateCcw, ShieldAlert, User } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';

const App: React.FC = () => {
  const [userName, setUserName] = useState<string>(() => localStorage.getItem('frogType_userName') || 'Froggy');
  const [joinDate, setJoinDate] = useState<string>(() => localStorage.getItem('frogType_joinDate') || new Date().toISOString());
  const [userXP, setUserXP] = useState<number>(() => parseInt(localStorage.getItem('frogXP') || '0', 10));

  const [masteredQuotes, setMasteredQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_masteredQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [strictRemediation, setStrictRemediation] = useState<StrictRemediation | null>(() => {
    const saved = localStorage.getItem('frogType_strictRemediation');
    return saved ? JSON.parse(saved) : null;
  });

  const [pendingWordDrill, setPendingWordDrill] = useState<WordDrill | null>(() => {
    const saved = localStorage.getItem('frogType_pendingWordDrill');
    return saved ? JSON.parse(saved) : null;
  });

  const [streak, setStreak] = useState<number>(() => parseInt(localStorage.getItem('frogType_streak') || '0', 10));
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => JSON.parse(localStorage.getItem('frogType_wpmHistory') || '[]'));
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => JSON.parse(localStorage.getItem('frogType_history') || '[]'));
  const [mistakePool, setMistakePool] = useState<string[]>(() => JSON.parse(localStorage.getItem('frogType_mistakes') || '[]'));
  const [gameMode, setGameMode] = useState<GameMode>(() => (localStorage.getItem('frogType_gameMode') as GameMode) || 'QUOTES');

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};
    return {
      ghostEnabled: false, 
      readAheadLevel: 'NONE', 
      sfxEnabled: true,
      mechanicalSoundEnabled: false,
      mechanicalSoundPreset: 'THOCK',
      ambientVolume: 0.02, 
      musicConfig: { source: 'NONE', presetId: '' },
      themeId: 'CLASSIC',
      autoStartMusic: true,
      ttsMode: 'OFF',
      ...parsed
    };
  });

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);

  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_masteredQuotes', JSON.stringify(masteredQuotes)); }, [masteredQuotes]);
  useEffect(() => { localStorage.setItem('frogType_strictRemediation', JSON.stringify(strictRemediation)); }, [strictRemediation]);
  useEffect(() => { localStorage.setItem('frogType_pendingWordDrill', JSON.stringify(pendingWordDrill)); }, [pendingWordDrill]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_gameMode', gameMode); }, [gameMode]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => root.style.setProperty(`--frog-${key}`, value));
    Object.entries(theme.colors.stone).forEach(([key, value]) => root.style.setProperty(`--stone-${key}`, value));
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  const loadMoreQuotes = useCallback(async () => {
    if (loading || strictRemediation || gameMode !== 'QUOTES') return;
    setLoading(true);
    try {
      const newQuotes = await fetchQuotes(5, masteredQuotes);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (e) { console.error(e); } 
    finally { setLoading(false); }
  }, [masteredQuotes, strictRemediation, loading, gameMode]);

  useEffect(() => {
    if (gameMode === 'QUOTES' && !currentQuote && !strictRemediation && !pendingWordDrill && quotesQueue.length === 0) {
        loadMoreQuotes();
    }
  }, [currentQuote, strictRemediation, pendingWordDrill, quotesQueue.length, loadMoreQuotes, gameMode]);

  useEffect(() => {
    if (gameMode === 'QUOTES' && !currentQuote && !pendingWordDrill) {
        if (strictRemediation) {
            setCurrentQuote({ text: strictRemediation.quoteText, source: strictRemediation.source, author: `Repetition ${strictRemediation.currentCount + 1}/${strictRemediation.requiredCount}` });
        } else if (quotesQueue.length > 0) {
            setCurrentQuote(quotesQueue[0]);
            setQuotesQueue(prev => prev.slice(1));
        }
    }
  }, [currentQuote, quotesQueue, strictRemediation, pendingWordDrill, gameMode]);

  const handleMistake = useCallback((word?: string) => {
    if (word) {
        const cleanWord = word.toLowerCase().replace(/[^a-z]/g, '');
        if (cleanWord.length > 0) {
          setPendingWordDrill({ word: cleanWord, requiredCount: 15, currentCount: 0 });
          soundEngine.playError();
        }
    }
  }, []);

  const handleQuoteComplete = (xp: number, wpm: number, mistakes: string[], retryCount: number) => {
    const isPerfect = mistakes.length === 0 && retryCount === 0;

    if (strictRemediation) {
        const nextCount = strictRemediation.currentCount + 1;
        if (nextCount >= strictRemediation.requiredCount) {
            setStrictRemediation(null);
            soundEngine.playLevelUp();
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
        } else {
            setStrictRemediation({ ...strictRemediation, currentCount: nextCount });
        }
        setCurrentQuote(null);
    } else {
        if (isPerfect) {
            setMasteredQuotes(prev => [...prev, currentQuote?.text || ""]);
            setUserXP(prev => prev + xp);
            setStreak(prev => prev + 1);
            soundEngine.playSuccess();
        } else {
            setStrictRemediation({
                quoteText: currentQuote?.text || "",
                author: currentQuote?.author || "",
                source: "Strict Mastery Required",
                requiredCount: 3,
                currentCount: 0
            });
            setStreak(0);
        }
        setWpmHistory(prev => [...prev, wpm].slice(-10));
        setTestHistory(prev => [...prev, { id: Date.now(), date: new Date().toISOString(), wpm, xpEarned: xp, mode: gameMode, quoteText: currentQuote?.text || "", mistakes, retryCount }]);
        setCurrentQuote(null);
    }
  };

  const handleDrillInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!pendingWordDrill) return;
    const val = e.target.value;
    const target = pendingWordDrill.word;

    if (val.endsWith(' ')) {
        const typed = val.trim().toLowerCase();
        if (typed === target) {
            const nextCount = pendingWordDrill.currentCount + 1;
            if (nextCount >= pendingWordDrill.requiredCount) {
                setPendingWordDrill(null);
                soundEngine.playSuccess();
            } else {
                setPendingWordDrill({ ...pendingWordDrill, currentCount: nextCount });
                soundEngine.playKeypress();
            }
        } else {
            setPendingWordDrill({ ...pendingWordDrill, currentCount: 0 });
            soundEngine.playError();
        }
        e.target.value = '';
    } else if (!target.startsWith(val.toLowerCase())) {
        setPendingWordDrill({ ...pendingWordDrill, currentCount: 0 });
        soundEngine.playError();
        e.target.value = '';
    } else {
        soundEngine.playKeypress();
    }
  };

  const isLocked = !!pendingWordDrill || !!strictRemediation;
  const avgWpmVal = getAverageWPM(wpmHistory);

  return (
    <div className={`min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200 transition-colors duration-1000 ${isLocked ? 'bg-stone-100' : ''}`}>
      <header className={`sticky top-0 z-40 bg-stone-50/90 backdrop-blur-md border-b border-stone-200/50 px-6 py-3 transition-all ${isLocked ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
        <div className="max-w-[1400px] mx-auto flex items-center justify-between">
          <h1 className="text-xl font-black text-frog-500 tracking-tight flex items-center gap-2 select-none">
            <span className="text-2xl drop-shadow-sm">🐸</span> Frog Type
          </h1>
          <div className="flex gap-2">
             <button onClick={() => setGameMode('QUOTES')} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${gameMode === 'QUOTES' ? 'bg-stone-200 text-frog-500 shadow-inner ring-1 ring-stone-300' : 'text-stone-400 hover:bg-stone-200 hover:text-stone-600'}`} title="Quotes Mode"><BookOpen className="w-4 h-4" /></button>
             <button onClick={() => setGameMode('TEN_FAST')} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${gameMode === 'TEN_FAST' ? 'bg-stone-200 text-frog-500 shadow-inner ring-1 ring-stone-300' : 'text-stone-400 hover:bg-stone-200 hover:text-stone-600'}`} title="10 Fast Sprint"><Zap className="w-4 h-4" /></button>
             <button onClick={() => setIsMusicOpen(true)} className={`p-2 transition-all rounded-xl ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'text-frog-500 bg-frog-50 shadow-sm ring-1 ring-frog-100' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`} title="Music Player"><Music className="w-5 h-5" /></button>
             <button onClick={() => setIsStatsOpen(true)} className="p-2 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded-xl transition-all" title="User Stats"><User className="w-5 h-5" /></button>
             <button onClick={() => setIsThemeOpen(true)} className="p-2 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded-xl transition-all" title="Themes"><Palette className="w-5 h-5" /></button>
             <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded-xl transition-all" title="Settings"><SettingsIcon className="w-5 h-5" /></button>
          </div>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 relative">
        {pendingWordDrill ? (
            <div className="w-full max-w-2xl bg-red-50 p-12 rounded-[3rem] border-4 border-red-100 shadow-2xl text-center animate-in zoom-in-95 duration-300">
                <div className="flex flex-col items-center gap-6">
                    <Brain className="w-16 h-16 text-red-500 animate-pulse" />
                    <h2 className="text-4xl font-black text-red-700 tracking-tight">STRICT DISCIPLINE</h2>
                    <p className="text-red-500 font-bold">Repeat the word <span className="underline font-black text-2xl">{pendingWordDrill.word}</span> 15 times to continue.</p>
                    <div className="relative mt-8 group">
                        <div className="text-7xl font-black text-red-200/40 tracking-widest uppercase">{pendingWordDrill.word}</div>
                        <input autoFocus className="absolute inset-0 bg-transparent text-center text-7xl font-black tracking-widest text-red-600 outline-none uppercase" onChange={handleDrillInput} />
                    </div>
                    <div className="mt-8 flex flex-col items-center">
                        <div className="text-red-400 font-black text-3xl font-mono">{pendingWordDrill.currentCount} / {pendingWordDrill.requiredCount}</div>
                        <div className="w-64 h-3 bg-red-100 rounded-full mt-2 overflow-hidden border border-red-200">
                            <div className="h-full bg-red-500 transition-all" style={{ width: `${(pendingWordDrill.currentCount/15)*100}%` }}></div>
                        </div>
                    </div>
                </div>
            </div>
        ) : gameMode === 'TEN_FAST' ? (
            <TenFastGame 
                smartQueue={[]} 
                onGameOver={(wpm, xp) => {
                    setUserXP(prev => prev + xp);
                    setWpmHistory(prev => [...prev, wpm].slice(-10));
                    soundEngine.playSuccess();
                }}
                onWordPerformance={() => {}}
                onExit={() => setGameMode('QUOTES')}
                onMistake={handleMistake}
            />
        ) : (
            <>
                {strictRemediation && (
                    <div className="mb-8 flex items-center gap-3 bg-amber-100 text-amber-800 px-6 py-3 rounded-full border border-amber-200 animate-bounce">
                        <ShieldAlert className="w-5 h-5" />
                        <span className="font-black tracking-tight uppercase text-sm">Strict Mastery Required: Complete 3x perfectly to unlock.</span>
                    </div>
                )}
                {currentQuote ? (
                    <TypingArea 
                        quote={currentQuote} 
                        onComplete={handleQuoteComplete} 
                        onFail={() => { setStreak(0); if (!strictRemediation) setStrictRemediation({ quoteText: currentQuote.text, author: currentQuote.author, source: "Mistake Penalty", requiredCount: 3, currentCount: 0 }); }}
                        onMistake={handleMistake} 
                        onRequestNewQuote={() => setCurrentQuote(null)}
                        streak={streak} 
                        ghostWpm={avgWpmVal} 
                        settings={settings} 
                        gameMode={gameMode} 
                    />
                ) : (
                    <div className="flex flex-col items-center text-stone-400">
                        <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-500" />
                        <p className="font-mono text-xs italic opacity-60">Seeking wisdom...</p>
                    </div>
                )}
            </>
        )}
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-stone-50/80 backdrop-blur-md border-t border-stone-200/50">
           <div className="max-w-[1400px] mx-auto flex items-center justify-between">
                <ProgressBar xp={userXP} avgWpm={avgWpmVal} mistakeCount={mistakePool.length} />
                <div className="flex gap-8 ml-8 shrink-0">
                    <div className="flex flex-col"><span className="text-[10px] font-black text-stone-300 uppercase tracking-widest">Mastered</span><span className="font-bold text-frog-500">{masteredQuotes.length}</span></div>
                    <div className="flex flex-col"><span className="text-[10px] font-black text-stone-300 uppercase tracking-widest">Streak</span><span className="font-bold text-orange-500">{streak}</span></div>
                </div>
           </div>
      </footer>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} setSettings={setSettings} />
      <ThemeModal isOpen={isThemeOpen} onClose={() => setIsThemeOpen(false)} currentThemeId={settings.themeId} setThemeId={(id) => setSettings({ ...settings, themeId: id })} currentLevel={getCurrentLevel(userXP)} allLevels={LEVELS} />
      <StatsModal isOpen={isStatsOpen} onClose={() => setIsStatsOpen(false)} avgWpm={avgWpmVal} history={testHistory} onPractice={() => {}} totalTime={0} joinDate={joinDate} streak={streak} userName={userName} setUserName={setUserName} completedTestsCount={testHistory.length} userXP={userXP} />
      <MusicPlayer isOpen={isMusicOpen} onClose={() => setIsMusicOpen(false)} settings={settings} setSettings={setSettings} userXP={userXP} />
    </div>
  );
};

export default App;

import React from 'react';
import { getCurrentLevel, LEVELS, checkLevelProgress } from '../utils/gameLogic';
import { Gauge } from 'lucide-react';

interface ProgressBarProps {
  xp: number;
  avgWpm: number;
  mistakeCount: number;
  remediationCount?: number;
}

const ProgressBar: React.FC<ProgressBarProps> = ({ xp, avgWpm, mistakeCount, remediationCount = 0 }) => {
  const { currentLevel, nextLevel } = checkLevelProgress(xp, avgWpm, mistakeCount, remediationCount);
  const currentLevelIndex = LEVELS.indexOf(currentLevel);
  const totalLevels = LEVELS.length;

  let levelProgress = 0;

  if (nextLevel) {
    const xpInLevel = xp - currentLevel.minXP;
    const levelSpan = nextLevel.minXP - currentLevel.minXP;
    levelProgress = Math.min(1, Math.max(0, xpInLevel / levelSpan));
  } else {
    levelProgress = 1;
  }

  const percentPerLevel = 100 / totalLevels;
  const globalProgress = (currentLevelIndex + levelProgress) * percentPerLevel;

  return (
    <div className="w-full flex flex-col justify-center">
      <div className="flex justify-between items-end mb-1 px-1">
        <div className="flex items-baseline gap-2">
          <span className={`text-xs font-black transition-colors duration-500 text-frog-500 uppercase tracking-widest`}>
             {currentLevel.name}
          </span>
          <span className="text-[9px] text-stone-400 font-mono opacity-80">{xp.toLocaleString()} / 1,000 XP</span>
        </div>

        <div className="text-right flex items-center gap-2">
           {nextLevel ? (
             <>
               <span className="text-[9px] text-stone-300 font-bold uppercase tracking-wider">Next:</span>
               <span className="text-[10px] font-black text-stone-500 uppercase">{nextLevel.name}</span>
               <span className="flex items-center gap-0.5 text-[9px] text-stone-300 ml-1 font-mono" title={`Target Speed: ${nextLevel.requiredWpm} WPM`}>
                  <Gauge className="w-2.5 h-2.5" /> {nextLevel.requiredWpm}
               </span>
             </>
           ) : (
               <span className="text-[10px] font-black text-frog-500 uppercase tracking-widest animate-pulse">Frog Sage Master</span>
           )}
        </div>
      </div>

      <div className="relative w-full h-5">
          <div className="absolute bottom-0 left-0 right-0 h-1.5 flex rounded-full overflow-hidden shadow-inner bg-stone-200/50 ring-1 ring-stone-200/20">
             {LEVELS.map((level, idx) => {
                 const isPassed = idx < currentLevelIndex;
                 const isCurrent = idx === currentLevelIndex;

                 // Use static tier-based color if not at the current level, 
                 // but ensure the current progress is themed
                 let bgStyle = { backgroundColor: `var(--stone-${idx * 100 + 100})` };
                 if (isPassed || isCurrent) {
                    bgStyle = { backgroundColor: 'var(--frog-400)' };
                 }

                 return (
                     <div 
                        key={level.name}
                        style={bgStyle}
                        className={`flex-1 transition-all duration-300 border-r border-white/10 last:border-0 ${idx > currentLevelIndex ? 'opacity-20' : 'opacity-100'}`}
                        title={level.name}
                     />
                 );
             })}
          </div>

          <div 
            className="absolute top-0 bottom-0 z-10 flex flex-col items-center justify-end pointer-events-none transition-all duration-700 ease-out"
            style={{ 
                left: `${globalProgress}%`,
                transform: `translateX(-50%)`
            }}
          >
             <div className="relative mb-0.5 transform-gpu hover:scale-110 transition-transform">
                 <span className="text-base block filter drop-shadow-[0_0_8px_var(--frog-300)] animate-pulse">
                    🐸
                 </span>
             </div>
             <div className="w-0.5 h-1 bg-stone-900/30 rounded-full mb-0.5"></div>
          </div>
      </div>
    </div>
  );
};

export default ProgressBar;

import { MechanicalSoundPreset } from '../types';

class SoundEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private warmthFilter: BiquadFilterNode | null = null;
  private enabled: boolean = true;
  private mechanicalEnabled: boolean = false;
  private mechanicalPreset: MechanicalSoundPreset = 'THOCK';
  private masterVolume: number = 1.0;

  // Ambient/Generated Music components
  private ambientInterval: number | null = null;
  private ambientGain: GainNode | null = null;
  private ambientType: string = '';
  private ambientVolume: number = 0.5;

  // FX for Ambient
  private delayNode: DelayNode | null = null;
  private feedbackNode: GainNode | null = null;
  private lowpassNode: BiquadFilterNode | null = null;
  private compressorNode: DynamicsCompressorNode | null = null;

  // Cached Buffers (Optimization)
  private noiseBuffers: { [key: string]: AudioBuffer } = {};

  // Sources
  private currentAmbientSources: AudioNode[] = [];
  private brownNoiseSource: AudioBufferSourceNode | null = null;

  // Sequence State
  private seqIndex: number = 0;

  constructor() {
    try {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      if (this.ctx) {
        this.generateNoiseBuffer('white', 2.0); 
      }
    } catch (e) {
      console.warn("Web Audio API not supported");
    }
  }

  private generateNoiseBuffer(type: 'white', duration: number) {
    if (!this.ctx) return;
    const bufferSize = this.ctx.sampleRate * duration;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
        data[i] = Math.random() * 2 - 1;
    }
    this.noiseBuffers[type] = buffer;
  }

  private ensureContext() {
    if (!this.ctx) return;
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    if (!this.masterGain) {
        this.masterGain = this.ctx.createGain();
        this.masterGain.gain.value = 1.0;

        // "Warmth" Filter - Softens high frequencies for a cozy lo-fi feel
        this.warmthFilter = this.ctx.createBiquadFilter();
        this.warmthFilter.type = 'lowpass';
        this.warmthFilter.frequency.value = 12000;
        this.warmthFilter.Q.value = 0.5;

        this.masterGain.connect(this.warmthFilter);
        this.warmthFilter.connect(this.ctx.destination);
    }
  }

  public setEnabled(enabled: boolean) {
    this.enabled = enabled;
  }

  public setMechanicalEnabled(enabled: boolean) {
    this.mechanicalEnabled = enabled;
  }

  public setMechanicalPreset(preset: MechanicalSoundPreset) {
    this.mechanicalPreset = preset;
  }

  public setAmbientVolume(volume: number) {
    this.ambientVolume = volume;
    if (this.ambientGain && this.ctx) {
        this.ambientGain.gain.setTargetAtTime(volume, this.ctx.currentTime, 0.2);
    }
  }

  public setAmbientMusic(presetId: string) {
    if (this.ambientType === presetId) return;
    this.stopAmbientMusic();
    if (presetId) {
      this.ambientType = presetId;
      this.startAmbientMusic();
    }
  }

  public stopAmbientMusic() {
    if (this.ambientInterval) {
      window.clearInterval(this.ambientInterval);
      this.ambientInterval = null;
    }

    if (this.ambientGain && this.ctx) {
      const t = this.ctx.currentTime;
      this.ambientGain.gain.setValueAtTime(this.ambientGain.gain.value, t);
      this.ambientGain.gain.linearRampToValueAtTime(0, t + 0.8); 

      const oldGain = this.ambientGain;
      this.currentAmbientSources.forEach(src => {
          try { (src as any).stop(); } catch(e) {}
      });
      this.currentAmbientSources = [];

      setTimeout(() => {
        try { oldGain.disconnect(); } catch (e) {}
      }, 1000);
    }

    this.ambientGain = null;
    this.ambientType = '';
    this.seqIndex = 0;
  }

  private startAmbientMusic() {
    this.ensureContext();
    if (!this.ctx || !this.masterGain) return;

    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0;
    this.ambientGain.gain.linearRampToValueAtTime(this.ambientVolume, this.ctx.currentTime + 1.0);

    this.compressorNode = this.ctx.createDynamicsCompressor();
    this.compressorNode.threshold.value = -24;
    this.compressorNode.attack.value = 0.003;
    this.compressorNode.release.value = 0.25;

    this.ambientGain.connect(this.compressorNode);
    this.compressorNode.connect(this.masterGain);

    // Common FX Chain
    this.delayNode = this.ctx.createDelay();
    this.delayNode.delayTime.value = 0.4; 
    this.feedbackNode = this.ctx.createGain();
    this.feedbackNode.gain.value = 0.3; 
    this.lowpassNode = this.ctx.createBiquadFilter();
    this.lowpassNode.type = 'lowpass';
    this.lowpassNode.frequency.value = 2500;

    this.delayNode.connect(this.feedbackNode);
    this.feedbackNode.connect(this.delayNode);
    this.delayNode.connect(this.lowpassNode);
    this.lowpassNode.connect(this.ambientGain);

    switch (this.ambientType) {
        case 'PIANO_BEETHOVEN': this.playBeethovenPiano(); break;
        case 'PIANO_SATIE': this.playSatiePiano(); break;
        case 'PIANO_JAZZ': this.playJazzPiano(); break;
        case 'ZEN': this.playProceduralZen(); break;
        case 'BROWN_NOISE': this.playBrownNoise(); break;
        case 'GUITAR': this.playAcousticGuitar(); break;
        case 'DRUMS_HARDCORE': this.playHardcoreDrums(); break;
        case 'SYNTH_COSMIC': this.playCosmicSynth(); break;
        case 'RAIN': this.playProceduralRain(); break;
        case 'FOREST': this.playMorningForest(); break;
    }
  }

  // --- NEW COZY NATURE ---

  private playProceduralRain() {
    if (!this.ctx || !this.ambientGain) return;

    // Constant Rain Wash
    const rainNoise = this.ctx.createBufferSource();
    rainNoise.buffer = this.noiseBuffers['white'];
    rainNoise.loop = true;

    const rainFilter = this.ctx.createBiquadFilter();
    rainFilter.type = 'bandpass';
    rainFilter.frequency.value = 1000;
    rainFilter.Q.value = 0.8;

    const rainGain = this.ctx.createGain();
    rainGain.gain.value = 0.4;

    rainNoise.connect(rainFilter);
    rainFilter.connect(rainGain);
    rainGain.connect(this.ambientGain);
    rainNoise.start(0);
    this.currentAmbientSources.push(rainNoise);

    // Random Droplets
    const triggerDrop = () => {
        if (this.ambientType !== 'RAIN' || !this.ctx) return;
        const t = this.ctx.currentTime;
        const osc = this.ctx.createOscillator();
        const g = this.ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(400 + Math.random() * 800, t);
        osc.frequency.exponentialRampToValueAtTime(100, t + 0.1);
        g.gain.setValueAtTime(0.05, t);
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
        osc.connect(g);
        g.connect(this.ambientGain!);
        osc.start(t);
        osc.stop(t + 0.1);
        this.ambientInterval = window.setTimeout(triggerDrop, 50 + Math.random() * 400);
    };
    triggerDrop();
  }

  private playMorningForest() {
    if (!this.ctx || !this.ambientGain) return;

    // Wind Wash
    const wind = this.ctx.createBufferSource();
    wind.buffer = this.noiseBuffers['white'];
    wind.loop = true;
    const windFilter = this.ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 400;
    wind.connect(windFilter);
    windFilter.connect(this.ambientGain);
    wind.start(0);
    this.currentAmbientSources.push(wind);

    // Procedural Birds
    const triggerBird = () => {
        if (this.ambientType !== 'FOREST' || !this.ctx) return;
        const t = this.ctx.currentTime;
        const carrier = this.ctx.createOscillator();
        const modulator = this.ctx.createOscillator();
        const modGain = this.ctx.createGain();
        const env = this.ctx.createGain();

        carrier.type = 'sine';
        modulator.type = 'sine';

        const baseFreq = 2500 + Math.random() * 2000;
        carrier.frequency.setValueAtTime(baseFreq, t);
        modulator.frequency.setValueAtTime(10 + Math.random() * 50, t);
        modGain.gain.setValueAtTime(1000, t);

        env.gain.setValueAtTime(0, t);
        env.gain.linearRampToValueAtTime(0.03, t + 0.05);
        env.gain.exponentialRampToValueAtTime(0.001, t + 0.3);

        modulator.connect(modGain);
        modGain.connect(carrier.frequency);
        carrier.connect(env);
        env.connect(this.ambientGain!);

        carrier.start(t);
        modulator.start(t);
        carrier.stop(t + 0.3);
        modulator.stop(t + 0.3);

        this.ambientInterval = window.setTimeout(triggerBird, 1000 + Math.random() * 5000);
    };
    triggerBird();
  }

  private playBrownNoise() {
    if (!this.ctx || !this.ambientGain) return;
    const bufferSize = 2 * this.ctx.sampleRate; 
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let lastOut = 0;
    for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;
        data[i] = (lastOut + (0.02 * white)) / 1.02;
        lastOut = data[i];
        data[i] *= 3.5; 
    }
    const src = this.ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 400; 
    src.connect(filter);
    filter.connect(this.ambientGain);
    src.start(0);
    this.currentAmbientSources.push(src);
  }

  // --- PIANOS ---

  private playBeethovenPiano() {
    const Gs3 = 207.65; const Cs4 = 277.18; const E4 = 329.63;
    const A3 = 220.00; const D4 = 293.66; const Fs3 = 185.00;
    const sequence = [
        [Gs3, 0.6], [Cs4, 0.6], [E4, 0.6], [Gs3, 0.6], [Cs4, 0.6], [E4, 0.6], 
        [A3, 0.6], [Cs4, 0.6], [E4, 0.6], [Fs3, 0.6], [A3, 0.6], [D4, 0.6],
    ];
    this.runSequence(sequence, (freq) => this.triggerPianoNote(freq, 'triangle'));
  }

  private playSatiePiano() {
    const Gmaj7 = [196.00, 246.94, 293.66, 369.99]; 
    const Dmaj7 = [146.83, 220.00, 277.18, 329.63]; 
    const sequence: any[] = [
        { notes: [98.00], duration: 1.5 }, { notes: Gmaj7, duration: 1.5 }, { notes: Gmaj7, duration: 1.5 },
        { notes: [73.42], duration: 1.5 }, { notes: Dmaj7, duration: 1.5 }, { notes: Dmaj7, duration: 1.5 },
    ];
    this.seqIndex = 0;
    const playNext = () => {
        if (!this.ambientType || !this.ctx) return;
        const step = sequence[this.seqIndex % sequence.length];
        this.seqIndex++;
        step.notes.forEach((freq: number) => this.triggerPianoNote(freq, 'sine', 0.15, 3.0));
        this.ambientInterval = window.setTimeout(playNext, step.duration * 1000);
    };
    playNext();
  }

  private playJazzPiano() {
    const Dm9 = [293.66, 349.23, 415.30, 440.00, 523.25];
    const G13 = [196.00, 246.94, 329.63, 440.00]; 
    const Cmaj9 = [261.63, 329.63, 392.00, 493.88, 587.33];
    const chords = [Dm9, G13, Cmaj9];
    const playNext = () => {
        if (!this.ambientType || !this.ctx) return;
        const chord = chords[Math.floor(Math.random() * chords.length)];
        chord.forEach((freq, i) => setTimeout(() => this.triggerPianoNote(freq, 'triangle', 0.1, 1.5), i * 30));
        if (Math.random() > 0.5) {
            setTimeout(() => {
                const scale = [523.25, 587.33, 659.25, 783.99, 880.00];
                this.triggerPianoNote(scale[Math.floor(Math.random() * scale.length)], 'sine', 0.08, 1.0);
            }, 800);
        }
        this.ambientInterval = window.setTimeout(playNext, 2000 + Math.random() * 2000);
    };
    playNext();
  }

  private triggerPianoNote(freq: number, type: OscillatorType = 'triangle', volume: number = 0.2, decay: number = 2.5) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const osc2 = this.ctx.createOscillator();
    osc.type = type;
    osc2.type = type;
    osc.frequency.setValueAtTime(freq, t);
    osc2.frequency.setValueAtTime(freq * 1.002, t);
    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(volume, t + 0.05);
    env.gain.exponentialRampToValueAtTime(0.001, t + decay);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(800, t);
    filter.frequency.linearRampToValueAtTime(100, t + decay);
    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);
    osc.start(t);
    osc2.start(t);
    osc.stop(t + decay + 0.1);
    osc2.stop(t + decay + 0.1);
  }

  private playAcousticGuitar() {
    const chords = [[196.00, 246.94, 293.66, 392.00], [164.81, 220.00, 261.63, 329.63], [146.83, 220.00, 293.66, 369.99], [130.81, 196.00, 261.63, 329.63]];
    const playStrum = () => {
        if (!this.ambientType || !this.ctx) return;
        const chord = chords[Math.floor(Math.random() * chords.length)];
        [0, 2, 1, 3, 2, 1].forEach((idx, i) => setTimeout(() => this.triggerGuitarPluck(chord[idx]), i * 250));
        this.ambientInterval = window.setTimeout(playStrum, 2000);
    };
    playStrum();
  }

  private triggerGuitarPluck(freq: number) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(freq, t);
    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.15, t + 0.02);
    env.gain.exponentialRampToValueAtTime(0.001, t + 1.5);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(3000, t);
    filter.frequency.exponentialRampToValueAtTime(100, t + 0.5);
    osc.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);
    osc.start(t);
    osc.stop(t + 1.5);
  }

  private playCosmicSynth() {
    const scale = [130.81, 155.56, 196.00, 233.08, 261.63];
    const playPad = () => {
        if (!this.ambientType || !this.ctx) return;
        this.triggerSynthPad(scale[Math.floor(Math.random() * scale.length)]);
        if (Math.random() > 0.7) this.triggerSynthPad(65.41, 6.0);
        this.ambientInterval = window.setTimeout(playPad, 4000 + Math.random() * 4000);
    };
    playPad();
  }

  private triggerSynthPad(freq: number, duration: number = 8.0) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const osc1 = this.ctx.createOscillator();
    const osc2 = this.ctx.createOscillator();
    osc1.type = 'sawtooth';
    osc2.type = 'square';
    osc1.frequency.setValueAtTime(freq, t);
    osc2.frequency.setValueAtTime(freq * 1.01, t);
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.2;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 400;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 600;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.15, t + 2.0);
    env.gain.linearRampToValueAtTime(0, t + duration);
    osc1.connect(filter);
    osc2.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    osc1.start(t); osc2.start(t); lfo.start(t);
    osc1.stop(t + duration); osc2.stop(t + duration); lfo.stop(t + duration);
  }

  private playHardcoreDrums() {
    const stepTime = 60 / 174 / 4;
    let step = 0;
    const loop = () => {
        if (!this.ambientType || !this.ctx) return;
        const b = step % 16;
        if (b === 0 || b === 10) this.triggerKick();
        if (b === 4 || b === 12) this.triggerSnare();
        if (b % 2 === 0) this.triggerHat();
        step++;
        this.ambientInterval = window.setTimeout(loop, stepTime * 1000);
    };
    loop();
  }

  private triggerKick() {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.frequency.setValueAtTime(150, t);
    osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5);
    g.gain.setValueAtTime(0.8, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
    osc.connect(g);
    g.connect(this.ambientGain);
    osc.start(t);
    osc.stop(t + 0.5);
  }

  private triggerSnare() {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const noise = this.ctx.createBufferSource();
    noise.buffer = this.noiseBuffers['white'];
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 1000;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.2, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
    noise.connect(filter);
    filter.connect(g);
    g.connect(this.ambientGain);
    noise.start(t);
    noise.stop(t + 0.2);
  }

  private triggerHat() {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const noise = this.ctx.createBufferSource();
    noise.buffer = this.noiseBuffers['white'];
    const f = this.ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 5000;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.1, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
    noise.connect(f);
    f.connect(g);
    g.connect(this.ambientGain);
    noise.start(t);
    noise.stop(t + 0.05);
  }

  private playProceduralZen() {
    const scale = [523.25, 587.33, 659.25, 783.99, 880.00];
    const playNote = () => {
      if (!this.ctx || !this.ambientGain) return;
      this.triggerBellNote(scale[Math.floor(Math.random() * scale.length)]);
      this.ambientInterval = window.setTimeout(playNote, 4000 + Math.random() * 4000);
    };
    playNote();
  }

  private triggerBellNote(freq: number) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);
    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.1, t + 0.02);
    env.gain.exponentialRampToValueAtTime(0.001, t + 4.0);
    osc.connect(env);
    env.connect(this.ambientGain);
    osc.start(t);
    osc.stop(t + 4.0);
  }

  private runSequence(sequence: any[], playFn: (f: number) => void) {
    const playNextNote = () => {
        if (!this.ambientType || !this.ctx) return;
        const noteData = sequence[this.seqIndex % sequence.length];
        this.seqIndex++;
        playFn(noteData[0]);
        this.ambientInterval = window.setTimeout(playNextNote, noteData[1] * 1000);
    };
    this.seqIndex = 0;
    playNextNote();
  }

  public playKeypress() {
     if (!this.enabled || !this.mechanicalEnabled || !this.ctx) return;
     this.ensureContext();

     // Subtle pitch randomization for organic feel
     const pitchFactor = 0.95 + Math.random() * 0.1;

     switch(this.mechanicalPreset) {
         case 'CLICKY': this.playClicky(pitchFactor); break;
         case 'BUBBLE': this.playBubble(pitchFactor); break;
         case 'TYPEWRITER': this.playTypewriter(pitchFactor); break;
         case 'THOCK':
         default: this.playThock(pitchFactor); break;
     }
  }

  private playThock(pf: number) {
     const t = this.ctx!.currentTime;
     const osc = this.ctx!.createOscillator();
     osc.type = 'triangle';
     osc.frequency.setValueAtTime((300 + Math.random()*50) * pf, t);
     osc.frequency.exponentialRampToValueAtTime(50, t + 0.08);
     const g = this.ctx!.createGain();
     g.gain.setValueAtTime(0.4, t);
     g.gain.exponentialRampToValueAtTime(0.01, t + 0.08);
     osc.connect(g);
     g.connect(this.masterGain!);
     osc.start(t);
     osc.stop(t + 0.1);
     this.playFilteredNoise(t, 2000 * pf, 0.15, 0.05);
  }

  private playClicky(pf: number) {
      const t = this.ctx!.currentTime;
      const osc = this.ctx!.createOscillator();
      osc.type = 'square';
      osc.frequency.setValueAtTime(1500 * pf, t);
      osc.frequency.exponentialRampToValueAtTime(500, t + 0.03);
      const g = this.ctx!.createGain();
      g.gain.setValueAtTime(0.08, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
      osc.connect(g);
      g.connect(this.masterGain!);
      osc.start(t);
      osc.stop(t + 0.04);
      this.playFilteredNoise(t, 4000 * pf, 0.1, 0.04, 'highpass');
  }

  private playBubble(pf: number) {
      const t = this.ctx!.currentTime;
      const osc = this.ctx!.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime((600 + Math.random()*100) * pf, t);
      osc.frequency.exponentialRampToValueAtTime(100, t + 0.1);
      const g = this.ctx!.createGain();
      g.gain.setValueAtTime(0.3, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
      osc.connect(g);
      g.connect(this.masterGain!);
      osc.start(t);
      osc.stop(t + 0.15);
  }

  private playTypewriter(pf: number) {
      const t = this.ctx!.currentTime;
      const osc = this.ctx!.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(2000 * pf, t);
      const g = this.ctx!.createGain();
      g.gain.setValueAtTime(0.05, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
      osc.connect(g);
      g.connect(this.masterGain!);
      osc.start(t);
      osc.stop(t + 0.06);
      this.playFilteredNoise(t, 1200 * pf, 0.3, 0.05, 'lowpass');
  }

  private playFilteredNoise(t: number, freq: number, vol: number, dur: number, type: BiquadFilterType = 'lowpass') {
      const noise = this.ctx!.createBufferSource();
      noise.buffer = this.noiseBuffers['white'];
      const f = this.ctx!.createBiquadFilter();
      f.type = type;
      f.frequency.setValueAtTime(freq, t);
      const g = this.ctx!.createGain();
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      noise.connect(f); f.connect(g);
      g.connect(this.masterGain!);
      noise.start(t);
      noise.stop(t + dur);
  }

  public playError() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    const t = this.ctx.currentTime;

    // Soft "Donk" Error - more cozy than a buzz
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(100, t);
    osc.frequency.exponentialRampToValueAtTime(40, t + 0.15);
    g.gain.setValueAtTime(0.2, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
    osc.connect(g);
    g.connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 0.15);

    // Tiny bubble pop overlay
    const pop = this.ctx.createOscillator();
    pop.type = 'sine';
    pop.frequency.setValueAtTime(800, t);
    pop.frequency.exponentialRampToValueAtTime(100, t + 0.05);
    const popG = this.ctx.createGain();
    popG.gain.setValueAtTime(0.1, t);
    popG.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
    pop.connect(popG);
    popG.connect(this.masterGain!);
    pop.start(t);
    pop.stop(t + 0.05);
  }

  public playSuccess() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    const t = this.ctx.currentTime;
    [523.25, 659.25, 783.99].forEach((freq, i) => {
        const osc = this.ctx!.createOscillator();
        const g = this.ctx!.createGain();
        osc.type = 'sine';
        osc.frequency.value = freq;
        g.gain.setValueAtTime(0.03, t + (i*0.05));
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
        osc.connect(g);
        g.connect(this.masterGain!);
        osc.start(t + (i*0.05));
        osc.stop(t + 0.5);
    });
  }

  public playLevelUp() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(220, t);
    osc.frequency.exponentialRampToValueAtTime(880, t + 0.4);
    g.gain.setValueAtTime(0.1, t);
    g.gain.linearRampToValueAtTime(0, t + 0.4);
    osc.connect(g);
    g.connect(this.masterGain!);
    osc.start(t);
    osc.stop(t + 0.4);
  }
}

