import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import BookMode from './components/BookMode';
import TenFastGame from './components/BlitzGame';
import DrillMode from './components/DrillMode';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, WordDrill, WordPerformance, BookSection, WordProficiency } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getAverageWPM, LEVELS } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, Library, BookOpen, Eraser, Palette, Brain, Zap, Lock, RotateCcw, ShieldAlert, User } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';

const App: React.FC = () => {
  const [userName, setUserName] = useState<string>(() => localStorage.getItem('frogType_userName') || 'Froggy');
  const [joinDate, setJoinDate] = useState<string>(() => localStorage.getItem('frogType_joinDate') || new Date().toISOString());
  const [userXP, setUserXP] = useState<number>(() => parseInt(localStorage.getItem('frogXP') || '0', 10));

  const [masteredQuotes, setMasteredQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_masteredQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [pendingWordDrill, setPendingWordDrill] = useState<WordDrill | null>(() => {
    const saved = localStorage.getItem('frogType_pendingWordDrill');
    return saved ? JSON.parse(saved) : null;
  });

  const [streak, setStreak] = useState<number>(() => parseInt(localStorage.getItem('frogType_streak') || '0', 10));
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => JSON.parse(localStorage.getItem('frogType_wpmHistory') || '[]'));
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => JSON.parse(localStorage.getItem('frogType_history') || '[]'));
  const [mistakePool, setMistakePool] = useState<string[]>(() => JSON.parse(localStorage.getItem('frogType_mistakes') || '[]'));
  const [gameMode, setGameMode] = useState<GameMode>(() => (localStorage.getItem('frogType_gameMode') as GameMode) || 'QUOTES');

  // Book Mode State
  const [bookContent, setBookContent] = useState<string | null>(() => localStorage.getItem('frogType_bookContent'));
  const [bookProgress, setBookProgress] = useState<number>(() => parseInt(localStorage.getItem('frogType_bookProgress') || '0', 10));
  const [bookStructure, setBookStructure] = useState<BookSection[] | null>(() => JSON.parse(localStorage.getItem('frogType_bookStructure') || 'null'));

  // Word Proficiency State
  const [wordProficiency, setWordProficiency] = useState<Record<string, WordProficiency>>(() => JSON.parse(localStorage.getItem('frogType_wordProficiency') || '{}'));

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};
    return {
      ghostEnabled: false, 
      readAheadLevel: 'NONE', 
      sfxEnabled: true,
      mechanicalSoundEnabled: false,
      mechanicalSoundPreset: 'THOCK',
      masterVolume: 1.0,
      ambientVolume: 0.02, 
      musicConfig: { source: 'NONE', presetId: '' },
      themeId: 'CLASSIC',
      autoStartMusic: true,
      ttsMode: 'OFF',
      strictDrillEnabled: false, // Default to OFF for a more relaxed experience
      ...parsed
    };
  });

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);

  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_masteredQuotes', JSON.stringify(masteredQuotes)); }, [masteredQuotes]);
  useEffect(() => { localStorage.setItem('frogType_pendingWordDrill', JSON.stringify(pendingWordDrill)); }, [pendingWordDrill]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_gameMode', gameMode); }, [gameMode]);

  useEffect(() => { 
    if (bookContent) localStorage.setItem('frogType_bookContent', bookContent);
    else localStorage.removeItem('frogType_bookContent');
  }, [bookContent]);

  useEffect(() => { 
    localStorage.setItem('frogType_bookProgress', bookProgress.toString());
  }, [bookProgress]);

  useEffect(() => {
    if (bookStructure) localStorage.setItem('frogType_bookStructure', JSON.stringify(bookStructure));
    else localStorage.removeItem('frogType_bookStructure');
  }, [bookStructure]);

  useEffect(() => {
    localStorage.setItem('frogType_wordProficiency', JSON.stringify(wordProficiency));
  }, [wordProficiency]);

  const updateWordProficiency = useCallback((word: string, isCorrect: boolean) => {
    const cleanWord = word.toLowerCase().replace(/[^a-z'-]/g, '');
    if (cleanWord.length < 2 || !isNaN(Number(cleanWord))) return;

    setWordProficiency(prev => {
        const current = prev[cleanWord] || { correct: 0, mistakes: 0 };
        if (isCorrect) {
            current.correct += 1;
        } else {
            current.mistakes += 1;
        }
        return { ...prev, [cleanWord]: current };
    });
  }, []);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => root.style.setProperty(`--frog-${key}`, value));
    Object.entries(theme.colors.stone).forEach(([key, value]) => root.style.setProperty(`--stone-${key}`, value));
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  // Centralized Sound Engine Controller
  useEffect(() => {
    soundEngine.setMasterVolume(settings.masterVolume);
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
        soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
        soundEngine.stopAmbientMusic();
    }
  }, [settings]);

  const loadMoreQuotes = useCallback(async () => {
    if (loading || gameMode !== 'QUOTES') return;
    setLoading(true);
    try {
      const newQuotes = await fetchQuotes(5, masteredQuotes);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (e) { console.error(e); } 
    finally { setLoading(false); }
  }, [masteredQuotes, loading, gameMode]);

  useEffect(() => {
    if (gameMode === 'QUOTES' && !currentQuote && !pendingWordDrill && quotesQueue.length === 0) {
        loadMoreQuotes();
    }
  }, [currentQuote, pendingWordDrill, quotesQueue.length, loadMoreQuotes, gameMode]);

  useEffect(() => {
    if (gameMode === 'QUOTES' && !currentQuote && !pendingWordDrill) {
        if (quotesQueue.length > 0) {
            setCurrentQuote(quotesQueue[0]);
            setQuotesQueue(prev => prev.slice(1));
        }
    }
  }, [currentQuote, quotesQueue, pendingWordDrill, gameMode]);

  const handleMistake = useCallback((word?: string) => {
    // Only trigger drill mode if explicitly enabled in settings
    if (!settings.strictDrillEnabled) return;

    if (word) {
        const cleanWord = word.toLowerCase().replace(/[^a-z]/g, '');
        if (cleanWord.length > 0) {
          setPendingWordDrill({ word: cleanWord, requiredCount: 15, currentCount: 0 });
          soundEngine.playError();
        }
    }
  }, [settings.strictDrillEnabled]);

  const handleQuoteComplete = (xp: number, wpm: number, mistakes: string[], retryCount: number) => {
    const isPerfect = mistakes.length === 0 && retryCount === 0;

    if (isPerfect) {
        setMasteredQuotes(prev => [...prev, currentQuote?.text || ""]);
        setUserXP(prev => prev + xp);
        setStreak(prev => prev + 1);
        soundEngine.playSuccess();
    } else {
        // Just reset streak on imperfect run, no forced remediation
        setStreak(0);
    }

    setWpmHistory(prev => [...prev, wpm].slice(-10));
    setTestHistory(prev => [...prev, { id: Date.now(), date: new Date().toISOString(), wpm, xpEarned: xp, mode: gameMode, quoteText: currentQuote?.text || "", mistakes, retryCount }]);
    setCurrentQuote(null);
  };

  const handleDrillInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!pendingWordDrill) return;
    const val = e.target.value;
    const target = pendingWordDrill.word;

    if (val.endsWith(' ')) {
        const typed = val.trim().toLowerCase();
        if (typed === target) {
            const nextCount = pendingWordDrill.currentCount + 1;
            if (nextCount >= pendingWordDrill.requiredCount) {
                setPendingWordDrill(null);
                soundEngine.playSuccess();
            } else {
                setPendingWordDrill({ ...pendingWordDrill, currentCount: nextCount });
                soundEngine.playKeypress();
            }
        } else {
            setPendingWordDrill({ ...pendingWordDrill, currentCount: 0 });
            soundEngine.playError();
        }
        e.target.value = '';
    } else if (!target.startsWith(val.toLowerCase())) {
        setPendingWordDrill({ ...pendingWordDrill, currentCount: 0 });
        soundEngine.playError();
        e.target.value = '';
    } else {
        soundEngine.playKeypress();
    }
  };

  const isLocked = !!pendingWordDrill;
  const avgWpmVal = getAverageWPM(wpmHistory);

  const renderGameMode = () => {
    switch(gameMode) {
      case 'TEN_FAST':
        return <TenFastGame 
            smartQueue={[]} 
            onGameOver={(wpm, xp) => {
                setUserXP(prev => prev + xp);
                setWpmHistory(prev => [...prev, wpm].slice(-10));
                soundEngine.playSuccess();
            }}
            onWordPerformance={() => {}}
            onExit={() => setGameMode('QUOTES')}
            onMistake={handleMistake}
        />;
      case 'BOOK':
        return <BookMode
          bookContent={bookContent}
          setBookContent={setBookContent}
          bookProgress={bookProgress}
          setBookProgress={setBookProgress}
          bookStructure={bookStructure}
          setBookStructure={setBookStructure}
          onXpEarned={(xp) => setUserXP(prev => prev + xp)}
          updateWordProficiency={updateWordProficiency}
        />;
      case 'DRILL':
        return <DrillMode
          wordProficiency={wordProficiency}
          updateWordProficiency={updateWordProficiency}
          onExit={() => setGameMode('QUOTES')}
        />;
      case 'QUOTES':
      default:
        return <>
            {currentQuote ? (
                <TypingArea 
                    quote={currentQuote} 
                    onComplete={handleQuoteComplete} 
                    onFail={() => setStreak(0)}
                    onMistake={handleMistake} 
                    onRequestNewQuote={() => setCurrentQuote(null)}
                    streak={streak} 
                    ghostWpm={avgWpmVal} 
                    settings={settings} 
                    gameMode={gameMode} 
                    updateWordProficiency={updateWordProficiency}
                />
            ) : (
                <div className="flex flex-col items-center text-stone-400">
                    <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-500" />
                    <p className="font-mono text-xs italic opacity-60">Seeking wisdom...</p>
                </div>
            )}
        </>;
    }
  };

  return (
    <div className={`min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200 transition-colors duration-1000 ${isLocked ? 'bg-stone-100' : ''}`}>
      <header className={`sticky top-0 z-40 bg-stone-50/90 backdrop-blur-md border-b border-stone-200/50 px-6 py-3 transition-all ${isLocked ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
        <div className="max-w-[1400px] mx-auto flex items-center justify-between">
          <h1 className="text-xl font-black text-frog-500 tracking-tight flex items-center gap-2 select-none">
            <span className="text-2xl drop-shadow-sm">🐸</span> Frog Type
          </h1>
          <div className="flex gap-2">
             <button onClick={() => setGameMode('QUOTES')} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${gameMode === 'QUOTES' ? 'bg-stone-200 text-frog-500 shadow-inner ring-1 ring-stone-300' : 'text-stone-400 hover:bg-stone-200 hover:text-stone-600'}`} title="Quotes Mode"><BookOpen className="w-4 h-4" /></button>
             <button onClick={() => setGameMode('TEN_FAST')} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${gameMode === 'TEN_FAST' ? 'bg-stone-200 text-frog-500 shadow-inner ring-1 ring-stone-300' : 'text-stone-400 hover:bg-stone-200 hover:text-stone-600'}`} title="10 Fast Sprint"><Zap className="w-4 h-4" /></button>
             <button onClick={() => setGameMode('BOOK')} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${gameMode === 'BOOK' ? 'bg-stone-200 text-frog-500 shadow-inner ring-1 ring-stone-300' : 'text-stone-400 hover:bg-stone-200 hover:text-stone-600'}`} title="Book Mode"><Library className="w-4 h-4" /></button>
             <button onClick={() => setGameMode('DRILL')} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${gameMode === 'DRILL' ? 'bg-stone-200 text-frog-500 shadow-inner ring-1 ring-stone-300' : 'text-stone-400 hover:bg-stone-200 hover:text-stone-600'}`} title="Drill Mistakes"><Brain className="w-4 h-4" /></button>
             <button onClick={() => setIsMusicOpen(true)} className={`p-2 transition-all rounded-xl ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'text-frog-500 bg-frog-50 shadow-sm ring-1 ring-frog-100' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`} title="Music Player"><Music className="w-5 h-5" /></button>
             <button onClick={() => setIsStatsOpen(true)} className="p-2 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded-xl transition-all" title="User Stats"><User className="w-5 h-5" /></button>
             <button onClick={() => setIsThemeOpen(true)} className="p-2 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded-xl transition-all" title="Themes"><Palette className="w-5 h-5" /></button>
             <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded-xl transition-all" title="Settings"><SettingsIcon className="w-5 h-5" /></button>
          </div>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 relative">
        {pendingWordDrill ? (
            <div className="w-full max-w-2xl bg-red-50 p-12 rounded-[3rem] border-4 border-red-100 shadow-2xl text-center animate-in zoom-in-95 duration-300">
                <div className="flex flex-col items-center gap-6">
                    <Brain className="w-16 h-16 text-red-500 animate-pulse" />
                    <h2 className="text-4xl font-black text-red-700 tracking-tight">STRICT DISCIPLINE</h2>
                    <p className="text-red-500 font-bold">Repeat the word <span className="underline font-black text-2xl">{pendingWordDrill.word}</span> 15 times to continue.</p>
                    <div className="relative mt-8 group">
                        <div className="text-7xl font-black text-red-200/40 tracking-widest uppercase">{pendingWordDrill.word}</div>
                        <input autoFocus className="absolute inset-0 bg-transparent text-center text-7xl font-black tracking-widest text-red-600 outline-none uppercase" onChange={handleDrillInput} />
                    </div>
                    <div className="mt-8 flex flex-col items-center">
                        <div className="text-red-400 font-black text-3xl font-mono">{pendingWordDrill.currentCount} / {pendingWordDrill.requiredCount}</div>
                        <div className="w-64 h-3 bg-red-100 rounded-full mt-2 overflow-hidden border border-red-200">
                            <div className="h-full bg-red-500 transition-all" style={{ width: `${(pendingWordDrill.currentCount/15)*100}%` }}></div>
                        </div>
                    </div>
                </div>
            </div>
        ) : renderGameMode()}
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-stone-50/80 backdrop-blur-md border-t border-stone-200/50">
           <div className="max-w-[1400px] mx-auto flex items-center justify-between">
                <ProgressBar xp={userXP} avgWpm={avgWpmVal} mistakeCount={mistakePool.length} />
                <div className="flex gap-8 ml-8 shrink-0">
                    <div className="flex flex-col"><span className="text-[10px] font-black text-stone-300 uppercase tracking-widest">Mastered</span><span className="font-bold text-frog-500">{masteredQuotes.length}</span></div>
                    <div className="flex flex-col"><span className="text-[10px] font-black text-stone-300 uppercase tracking-widest">Streak</span><span className="font-bold text-orange-500">{streak}</span></div>
                </div>
           </div>
      </footer>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} setSettings={setSettings} />
      <ThemeModal isOpen={isThemeOpen} onClose={() => setIsThemeOpen(false)} currentThemeId={settings.themeId} setThemeId={(id) => setSettings({ ...settings, themeId: id })} currentLevel={getCurrentLevel(userXP)} allLevels={LEVELS} />
      <StatsModal isOpen={isStatsOpen} onClose={() => setIsStatsOpen(false)} avgWpm={avgWpmVal} history={testHistory} onPractice={() => {}} totalTime={0} joinDate={joinDate} streak={streak} userName={userName} setUserName={setUserName} completedTestsCount={testHistory.length} userXP={userXP} />
      <MusicPlayer isOpen={isMusicOpen} onClose={() => setIsMusicOpen(false)} settings={settings} setSettings={setSettings} userXP={userXP} />
    </div>
  );
};

export default App;

import React, { useRef } from 'react';
import { Settings, MechanicalSoundPreset, ReadAheadLevel, TTSMode } from '../types';
import { X, Ghost, EyeOff, Volume2, Music, Download, Upload, Database, Keyboard, Eye, PlayCircle, AlertTriangle, CheckCircle2, Speech, ShieldAlert } from 'lucide-react';
import { getCurrentLevel } from '../utils/gameLogic';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: Settings;
  setSettings: (s: Settings) => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, settings, setSettings }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const toggleGhost = () => setSettings({ ...settings, ghostEnabled: !settings.ghostEnabled });
  const setReadAheadLevel = (level: ReadAheadLevel) => setSettings({ ...settings, readAheadLevel: level });
  const toggleSfx = () => setSettings({ ...settings, sfxEnabled: !settings.sfxEnabled });
  const toggleMechanical = () => setSettings({ ...settings, mechanicalSoundEnabled: !settings.mechanicalSoundEnabled });
  const setMechanicalPreset = (preset: MechanicalSoundPreset) => setSettings({ ...settings, mechanicalSoundPreset: preset });
  const toggleAutoStart = () => setSettings({ ...settings, autoStartMusic: !settings.autoStartMusic });
  const toggleStrictDrill = () => setSettings({ ...settings, strictDrillEnabled: !settings.strictDrillEnabled });
  const setTTSMode = (mode: TTSMode) => setSettings({ ...settings, ttsMode: mode });

  const handleExport = () => {
    const backupData: Record<string, string> = {};
    let itemCount = 0;

    // 1. Capture all relevant LocalStorage keys
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      // Capture all keys related to Frog Type namespace + the legacy/root XP key
      if (key && (key.startsWith('frogType_') || key === 'frogXP')) {
        const value = localStorage.getItem(key);
        if (value !== null) {
            backupData[key] = value;
            itemCount++;
        }
      }
    }

    if (itemCount === 0) {
        alert("No game data found to export.");
        return;
    }

    // 2. Wrap in a structured object with metadata
    const payload = {
        meta: {
            version: 2, // Increment version for the new system
            app: "Frog Type",
            timestamp: new Date().toISOString(),
            itemCount: itemCount
        },
        data: backupData
    };

    // 3. Trigger Download
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    // Filename includes date for version control
    a.download = `frog-type-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonStr = event.target?.result as string;
        const parsed = JSON.parse(jsonStr);

        let dataToRestore: Record<string, string> = {};

        // --- VALIDATION & DETECTION ---

        // Check 1: Is this the new format (v2)?
        if (parsed.meta && parsed.data && parsed.meta.app === "Frog Type") {
            dataToRestore = parsed.data;
        } 
        // Check 2: Is this the legacy flat format?
        else {
            // Check if it has at least one recognizable key
            const keys = Object.keys(parsed);
            const hasValidKeys = keys.some(k => k.startsWith('frogType_') || k === 'frogXP');

            if (hasValidKeys) {
                dataToRestore = parsed;
            } else {
                throw new Error("Unrecognized file format");
            }
        }

        // --- PREVIEW LOGIC ---
        // Extract stats from the backup to show the user what they are loading
        const backupXP = parseInt(dataToRestore['frogXP'] || dataToRestore['frogType_xp'] || '0', 10);
        const backupName = dataToRestore['frogType_userName'] || 'Froggy';
        const backupLevel = getCurrentLevel(backupXP);
        const backupStreak = dataToRestore['frogType_dailyStreak'] || '0';

        const confirmMessage = `
Found Backup Profile:
👤 Name: ${backupName}
🐸 Rank: ${backupLevel.name}
🔥 Streak: ${backupStreak}
✨ XP: ${backupXP.toLocaleString()}

This will OVERWRITE your current data on this device.
Are you sure you want to restore?
        `.trim();

        if (window.confirm(confirmMessage)) {
            // 1. Clear existing Frog Type data to prevent conflicts
            const keysToRemove: string[] = [];
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                if (key && (key.startsWith('frogType_') || key === 'frogXP')) {
                    keysToRemove.push(key);
                }
            }
            keysToRemove.forEach(k => localStorage.removeItem(k));

            // 2. Write new data
            Object.entries(dataToRestore).forEach(([key, value]) => {
                 // Double check we only write frog keys (security measure)
                 if (key.startsWith('frogType_') || key === 'frogXP') {
                     localStorage.setItem(key, value);
                 }
            });

            alert("Backup restored successfully! The page will now reload.");
            window.location.reload();
        }
      } catch (err) {
        alert("Failed to restore backup: Invalid file format or corrupted data.");
        console.error(err);
      }

      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div 
      className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-stone-900/20 backdrop-blur-sm animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div 
        className="bg-white rounded-2xl shadow-xl w-full max-w-sm overflow-hidden flex flex-col max-h-[85vh]"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex justify-between items-center p-4 border-b border-stone-100 bg-white sticky top-0 z-10">
          <h2 className="text-lg font-bold text-stone-700 flex items-center gap-2">
            Settings
          </h2>
          <button onClick={onClose} className="text-stone-400 hover:text-stone-600 focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 rounded-full p-1">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 space-y-4 overflow-y-auto custom-scrollbar">

          {/* Sound Effects Toggle (Teal) */}
          <button 
            onClick={toggleSfx}
            className={`w-full text-left flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all focus:outline-none focus:ring-2 focus:ring-teal-500 focus:ring-offset-1 ${settings.sfxEnabled ? 'bg-teal-50 border-teal-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.sfxEnabled ? 'bg-teal-100 text-teal-600' : 'bg-stone-200 text-stone-500'}`}>
                <Volume2 className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Sound Effects</div>
                <div className="text-[10px] text-stone-400">Game status sounds</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.sfxEnabled ? 'bg-teal-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.sfxEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </button>

          {/* Auto-Start Music Toggle (Green) */}
          <button 
            onClick={toggleAutoStart}
            className={`w-full text-left flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-1 ${settings.autoStartMusic ? 'bg-frog-50 border-frog-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.autoStartMusic ? 'bg-frog-100 text-frog-600' : 'bg-stone-200 text-stone-500'}`}>
                <PlayCircle className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Auto-Start Music</div>
                <div className="text-[10px] text-stone-400">Play background music on load</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.autoStartMusic ? 'bg-frog-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.autoStartMusic ? 'left-5' : 'left-1'}`} />
            </div>
          </button>

          {/* Strict Word Drill Toggle (Red) */}
          <button 
            onClick={toggleStrictDrill}
            className={`w-full text-left flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-1 ${settings.strictDrillEnabled ? 'bg-red-50 border-red-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.strictDrillEnabled ? 'bg-red-100 text-red-600' : 'bg-stone-200 text-stone-500'}`}>
                <ShieldAlert className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Strict Word Drill</div>
                <div className="text-[10px] text-stone-400">Force 15x repetition on error</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.strictDrillEnabled ? 'bg-red-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.strictDrillEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </button>

          {/* Text-to-Speech Selector (Orange) */}
          <div className={`rounded-xl border transition-all overflow-hidden ${settings.ttsMode !== 'OFF' ? 'bg-orange-50 border-orange-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}>
              <div className="p-3">
                <div className="flex items-center gap-3 mb-2">
                  <div className={`p-2 rounded-lg ${settings.ttsMode !== 'OFF' ? 'bg-orange-100 text-orange-600' : 'bg-stone-200 text-stone-500'}`}>
                    <Speech className="w-5 h-5" />
                  </div>
                  <div>
                    <div className="font-bold text-sm text-stone-700">Read Aloud Mode</div>
                    <div className="text-[10px] text-stone-400">Speak words while typing</div>
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-1 p-1 bg-stone-200/50 rounded-lg">
                    {(['OFF', 'QUOTE', 'WORD', 'FLOW', 'NEXT', 'SCOUT'] as TTSMode[]).map(mode => {
                        const labels = { 
                            OFF: 'Off', 
                            QUOTE: 'Full Quote', 
                            WORD: 'Current', 
                            FLOW: 'Flow',
                            NEXT: 'Next',
                            SCOUT: 'Scout (+2)'
                        };
                        const isActive = settings.ttsMode === mode;

                        let activeClass = 'bg-white text-stone-700 shadow-sm';
                        // Orange theme for TTS active states
                        if (isActive && mode !== 'OFF') activeClass = 'bg-orange-500 text-white shadow-sm';

                        return (
                           <button
                             key={mode}
                             onClick={() => setTTSMode(mode)}
                             className={`
                                text-[9px] font-bold py-1.5 px-1 rounded-md transition-all flex flex-col items-center justify-center
                                focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-1
                                ${isActive ? activeClass : 'text-stone-500 hover:bg-white/50'}
                             `}
                           >
                               <span>{labels[mode]}</span>
                           </button>
                        );
                    })}
                </div>
              </div>
          </div>

          {/* Mechanical Sounds Toggle (Amber) */}
          <div className={`rounded-xl border transition-all overflow-hidden ${settings.mechanicalSoundEnabled ? 'bg-amber-50 border-amber-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}>
              <button 
                onClick={toggleMechanical}
                className="w-full text-left flex items-center justify-between p-3 cursor-pointer focus:outline-none focus:ring-2 focus:ring-amber-500 focus:ring-inset"
              >
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-lg ${settings.mechanicalSoundEnabled ? 'bg-amber-100 text-amber-600' : 'bg-stone-200 text-stone-500'}`}>
                    <Keyboard className="w-5 h-5" />
                  </div>
                  <div>
                    <div className="font-bold text-sm text-stone-700">Mechanical Keys</div>
                    <div className="text-[10px] text-stone-400">Typewriter click sounds</div>
                  </div>
                </div>
                <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.mechanicalSoundEnabled ? 'bg-amber-500' : 'bg-stone-300'}`}>
                   <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.mechanicalSoundEnabled ? 'left-5' : 'left-1'}`} />
                </div>
              </button>

              {/* Preset Selector */}
              {settings.mechanicalSoundEnabled && (
                  <div className="px-3 pb-3 pt-0 animate-in slide-in-from-top-2">
                      <div className="grid grid-cols-4 gap-1 p-1 bg-amber-100/50 rounded-lg">
                          {(['THOCK', 'CLICKY', 'BUBBLE', 'TYPEWRITER'] as MechanicalSoundPreset[]).map(preset => (
                              <button
                                key={preset}
                                onClick={(e) => { e.stopPropagation(); setMechanicalPreset(preset); }}
                                className={`
                                    text-[10px] font-bold py-1.5 px-1 rounded-md transition-all focus:outline-none focus:ring-2 focus:ring-amber-500 focus:ring-offset-1
                                    ${settings.mechanicalSoundPreset === preset 
                                        ? 'bg-white text-amber-600 shadow-sm' 
                                        : 'text-amber-700/60 hover:bg-amber-100/50'}
                                `}
                              >
                                  {preset === 'TYPEWRITER' ? 'TYPE' : preset}
                              </button>
                          ))}
                      </div>
                  </div>
              )}
          </div>

          {/* Ghost Mode Toggle */}
          <button 
            onClick={toggleGhost}
            className={`w-full text-left flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-1 ${settings.ghostEnabled ? 'bg-purple-50 border-purple-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.ghostEnabled ? 'bg-purple-100 text-purple-600' : 'bg-stone-200 text-stone-500'}`}>
                <Ghost className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Ghost Replay</div>
                <div className="text-[10px] text-stone-400">Race against your previous speed</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.ghostEnabled ? 'bg-purple-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.ghostEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </button>

          {/* Read Ahead Selector */}
          <div className={`rounded-xl border transition-all overflow-hidden ${settings.readAheadLevel !== 'NONE' ? 'bg-frog-green/5 border-frog-green/20' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}>
              <div className="p-3">
                <div className="flex items-center gap-3 mb-2">
                  <div className={`p-2 rounded-lg ${settings.readAheadLevel !== 'NONE' ? 'bg-frog-green/10 text-frog-green' : 'bg-stone-200 text-stone-500'}`}>
                    <EyeOff className="w-5 h-5" />
                  </div>
                  <div>
                    <div className="font-bold text-sm text-stone-700">Read Ahead Mode</div>
                    <div className="text-[10px] text-stone-400">Hide text to force focus</div>
                  </div>
                </div>

                <div className="grid grid-cols-4 gap-1 p-1 bg-stone-200/50 rounded-lg">
                    {(['NONE', 'FOCUS', 'ULTRA', 'BLIND'] as ReadAheadLevel[]).map(level => {
                        const labels = { NONE: 'Off', FOCUS: 'Focus', ULTRA: 'Ultra', BLIND: 'Blind' };
                        const bonuses = { NONE: '', FOCUS: '+10%', ULTRA: '+20%', BLIND: '+30%' };
                        const isActive = settings.readAheadLevel === level;

                        let activeClass = 'bg-white text-stone-700 shadow-sm';
                        if (isActive && level === 'FOCUS') activeClass = 'bg-frog-green text-white shadow-sm';
                        if (isActive && level === 'ULTRA') activeClass = 'bg-purple-500 text-white shadow-sm';
                        if (isActive && level === 'BLIND') activeClass = 'bg-red-500 text-white shadow-sm';

                        return (
                           <button
                             key={level}
                             onClick={() => setReadAheadLevel(level)}
                             className={`
                                text-[10px] font-bold py-1.5 px-1 rounded-md transition-all flex flex-col items-center justify-center gap-0.5
                                focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-1
                                ${isActive ? activeClass : 'text-stone-500 hover:bg-white/50'}
                             `}
                           >
                               <span>{labels[level]}</span>
                               {bonuses[level] && <span className="text-[8px] opacity-80">{bonuses[level]}</span>}
                           </button>
                        );
                    })}
                </div>
              </div>
          </div>

          {/* Backup & Restore Section */}
          <div className="pt-4 border-t border-stone-100">
             <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2 text-stone-700 font-bold text-xs uppercase tracking-wider">
                    <Database className="w-3.5 h-3.5 text-frog-green" /> Cloud Save (Manual)
                </div>
                <div className="flex items-center gap-1 text-[9px] text-stone-400 bg-stone-100 px-1.5 py-0.5 rounded">
                    <span>v2.0</span>
                </div>
             </div>

             <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={handleExport}
                  className="group flex flex-col items-center justify-center gap-2 p-3 rounded-xl bg-stone-50 border border-stone-200 hover:bg-frog-green/5 hover:border-frog-green/30 transition-all text-stone-600 hover:text-frog-green focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-1"
                >
                    <Download className="w-5 h-5 group-hover:-translate-y-0.5 transition-transform" />
                    <span className="text-xs font-bold">Backup File</span>
                </button>
                <button 
                  onClick={handleImportClick}
                  className="group flex flex-col items-center justify-center gap-2 p-3 rounded-xl bg-stone-50 border border-stone-200 hover:bg-purple-50 hover:border-purple-200 transition-all text-stone-600 hover:text-purple-600 relative focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-1"
                >
                    <Upload className="w-5 h-5 group-hover:-translate-y-0.5 transition-transform" />
                    <span className="text-xs font-bold">Restore</span>
                    <input 
                        type="file" 
                        ref={fileInputRef}
                        onChange={handleImportFile}
                        accept=".json"
                        className="hidden"
                    />
                </button>
             </div>

             <div className="mt-3 p-2 bg-blue-50 border border-blue-100 rounded-lg flex gap-2">
                <div className="shrink-0 pt-0.5"><CheckCircle2 className="w-3 h-3 text-blue-500" /></div>
                <p className="text-[10px] text-blue-700 leading-tight">
                    Includes <strong>everything</strong>: XP, streaks, settings, history, unlocked themes, and stats. Safe to transfer between devices.
                </p>
             </div>
          </div>

        </div>

        <div className="p-4 bg-stone-50 text-center border-t border-stone-100">
            <button onClick={onClose} className="text-xs font-bold text-stone-500 hover:text-stone-700 focus:outline-none focus:underline">Close</button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;
